"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export type MaskPreset = "circle" | "blob" | "stripes" | "text"

export interface SvgMaskScrollTransitionProps {
  className?: string
  intensity?: number
  speed?: number
  count?: number
}

function pace(speed: number | undefined) {
  return speed === undefined || !Number.isFinite(speed) || speed <= 0 ? 1 : speed
}

const PRESETS: readonly { id: MaskPreset; label: string }[] = [
  { id: "circle", label: "圆形" },
  { id: "blob", label: "色块" },
  { id: "stripes", label: "条纹" },
  { id: "text", label: "文字" },
]

function SvgMaskScrollTransition({ className, intensity, speed, count }: SvgMaskScrollTransitionProps) {
  const reduced = usePrefersReducedMotion()
  const reactId = React.useId().replace(/:/g, "")
  const maskId = `effect-ui-mask-${reactId}`
  const [progress, setProgress] = React.useState(reduced ? 1 : 0)
  const [preset, setPreset] = React.useState<MaskPreset>("circle")
  const rate = pace(speed)
  const gain = intensity === undefined || intensity === 1 ? 1 : intensity
  const stripes = count === undefined || count === 7 ? 7 : Math.max(1, Math.round(count))

  const onScroll = (event: React.UIEvent<HTMLDivElement>) => {
    if (reduced) return
    const element = event.currentTarget
    const max = element.scrollHeight - element.clientHeight
    const next = max <= 0 ? 1 : element.scrollTop / max
    setProgress(next)
  }

  const shaped = rate === 1 ? progress : Math.min(1, Math.pow(Math.max(progress, 0), rate))
  const amount = reduced ? 1 : shaped

  return (
    <div data-slot="svg-mask-scroll-transition" className={cn("w-full space-y-3", className)}>
      <div className="flex flex-wrap gap-2" role="radiogroup" aria-label="遮罩形状">
        {PRESETS.map((item) => (
          <button
            key={item.id}
            type="button"
            role="radio"
            aria-checked={preset === item.id}
            className={cn("rounded-md border px-3 py-1.5 text-sm", preset === item.id && "bg-primary text-primary-foreground")}
            onClick={() => setPreset(item.id)}
          >
            {item.label}
          </button>
        ))}
      </div>
      <div
        tabIndex={0}
        aria-label="滚动切换场景。下一幕从 SVG 遮罩里显出。"
        className="h-80 overflow-auto rounded-xl border outline-none focus-visible:ring-2 focus-visible:ring-primary"
        onScroll={onScroll}
      >
        <div className="relative h-[180vh]">
          <div className="sticky top-0 h-80 overflow-hidden">
            <div className="absolute inset-0 grid place-items-center bg-[linear-gradient(145deg,#1e1b4b,#0f766e)] text-3xl font-medium text-white">
              上一幕
            </div>
            <div
              className="absolute inset-0 grid place-items-center bg-[linear-gradient(160deg,#9a3412,#f59e0b)] text-3xl font-medium text-white"
              style={{ mask: `url(#${maskId})`, WebkitMask: `url(#${maskId})` }}
            >
              下一幕
            </div>
            <svg className="pointer-events-none absolute h-0 w-0" aria-hidden>
              <mask id={maskId} maskContentUnits="objectBoundingBox">
                {preset === "circle" ? (
                  <circle cx="0.5" cy="0.5" r={gain === 1 ? 0.04 + amount * 0.72 : 0.04 + amount * 0.72 * gain} fill="white" />
                ) : null}
                {preset === "blob" ? (
                  <>
                    <ellipse cx="0.46" cy="0.48" rx={gain === 1 ? 0.08 + amount * 0.42 : 0.08 + amount * 0.42 * gain} ry={gain === 1 ? 0.06 + amount * 0.34 : 0.06 + amount * 0.34 * gain} fill="white" />
                    <ellipse cx="0.62" cy="0.58" rx={gain === 1 ? 0.05 + amount * 0.24 : 0.05 + amount * 0.24 * gain} ry={gain === 1 ? 0.08 + amount * 0.22 : 0.08 + amount * 0.22 * gain} fill="white" />
                  </>
                ) : null}
                {preset === "stripes"
                  ? Array.from({ length: stripes }, (_, index) => (
                      <rect
                        key={index}
                        x={index / stripes + 0.008}
                        y={1 - (gain === 1 ? amount : amount * gain)}
                        width={1 / stripes - 0.016}
                        height={gain === 1 ? amount : amount * gain}
                        fill="white"
                      />
                    ))
                  : null}
                {preset === "text" ? (
                  <text
                    x="0.5"
                    y="0.58"
                    textAnchor="middle"
                    fill="white"
                    fontSize={gain === 1 ? 0.05 + amount * 0.42 : 0.05 + amount * 0.42 * gain}
                    fontFamily="sans-serif"
                  >
                    OPEN
                  </text>
                ) : null}
              </mask>
            </svg>
          </div>
        </div>
      </div>
    </div>
  )
}

export { SvgMaskScrollTransition }

"use client"

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/switchboard-card/index.tsx

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { useAnimationActive } from "@/hooks/use-animation-active"

import { cn } from "@/lib/utils"
import { useEffect, useMemo, useRef, useState } from "react";

export type LightState = "off" | "medium" | "high";

export interface SwitchboardCardProps {
  className?: string;
  columns?: number;
  gridPattern?: number[] | number[][]; // Direct grid pattern: flat array (columns*rows) or 2D array [rows][columns] where 0=off, 1=high
  href?: string;
  onButtonClick?: () => void;
  randomLights?: boolean; // If true, randomly activate some lights
  rows?: number;
  showButton?: boolean;
  subtitle: string;
  title: string;
  transitionDuration?: number; // in milliseconds (default: 200ms for smooth light transitions)
  variant?: "default" | "next";
}

function generateRandomPattern(
  totalLights: number,
  activeRatio = 0.15
): number[] {
  const activeCount = Math.floor(totalLights * activeRatio);
  const pattern: number[] = [];
  const used = new Set<number>();

  while (pattern.length < activeCount) {
    const index = Math.floor(Math.random() * totalLights);
    if (!used.has(index)) {
      used.add(index);
      pattern.push(index);
    }
  }

  return pattern.sort((a, b) => a - b);
}

function parse2DGridPattern(
  grid2D: number[][],
  rows: number,
  columns: number,
  totalLights: number
): number[] {
  const pattern: number[] = [];
  for (let row = 0; row < Math.min(grid2D.length, rows); row++) {
    const rowData = grid2D[row];
    if (Array.isArray(rowData)) {
      for (let col = 0; col < Math.min(rowData.length, columns); col++) {
        if (rowData[col] === 1) {
          const index = col + row * columns;
          if (index >= 0 && index < totalLights) {
            pattern.push(index);
          }
        }
      }
    }
  }
  return pattern;
}

function parseFlatGridPattern(
  flatPattern: number[],
  totalLights: number
): number[] {
  const pattern: number[] = [];
  for (let i = 0; i < Math.min(flatPattern.length, totalLights); i++) {
    if (flatPattern[i] === 1) {
      pattern.push(i);
    }
  }
  return pattern;
}

export function SwitchboardCard({
  title,
  subtitle,
  columns = 18,
  rows = 5,
  gridPattern,
  randomLights = false,
  transitionDuration = 200,
  className,
  variant = "default",
  href,
  onButtonClick,
}: SwitchboardCardProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(rootRef);
  const shouldReduceMotion = usePrefersReducedMotion();
  const totalLights = columns * rows;
  const isRandomLightsMode = randomLights && !gridPattern;

  // Convert gridPattern to light indices
  // Priority: gridPattern > randomLights
  const basePattern = useMemo<number[]>(() => {
    if (gridPattern) {
      // Handle 2D array [rows][columns]
      const is2DArray =
        Array.isArray(gridPattern[0]) && typeof gridPattern[0] !== "number";
      if (is2DArray) {
        return parse2DGridPattern(
          gridPattern as number[][],
          rows,
          columns,
          totalLights
        );
      }
      // Handle flat array [columns*rows]
      return parseFlatGridPattern(gridPattern as number[], totalLights);
    }
    if (randomLights) {
      return generateRandomPattern(totalLights);
    }
    return [];
  }, [gridPattern, randomLights, columns, rows, totalLights]);

  // Animated light states
  // For random lights: all start off, will animate randomly through medium → high → medium → off
  // For word/pattern: pattern lights start high (stay high), rest off
  const [lightStates, setLightStates] = useState<LightState[]>(() => {
    const states: LightState[] = new Array(totalLights).fill("off");
    if (!isRandomLightsMode) {
      // For word/pattern, set pattern lights to high
      for (const index of basePattern) {
        if (index >= 0 && index < totalLights) {
          states[index] = "high";
        }
      }
    }
    // For random lights, all start off (will animate)
    return states;
  });

  // Animate lights - only for random lights mode (word/pattern stays high)
  useEffect(() => {
    // Word/pattern mode: no animation, lights stay high
    if (!isRandomLightsMode || !motionOn || shouldReduceMotion) {
      return;
    }

    const interval = setInterval(() => {
      setLightStates((prev) => {
        const next = [...prev];
        // For random lights: animate all lights randomly through off → high (via medium transition)
        // Randomly select a subset of lights to animate each tick
        const lightsToAnimate = Math.floor(totalLights * 0.2); // Animate ~20% of all lights per tick
        const allIndices = Array.from({ length: totalLights }, (_, i) => i);
        const shuffled = allIndices.sort(() => Math.random() - 0.5);

        for (let i = 0; i < Math.min(lightsToAnimate, shuffled.length); i++) {
          const index = shuffled[i];
          if (index! >= 0 && index! < totalLights) {
            const current = prev[index!];
            // State transition logic for random lights: off → high (with medium as intermediate transition state)
            // Medium state is only used as a transition, not a final state
            if (current === "off") {
              // Start transition to high by going to medium first
              next[index!] = "medium";
            } else if (current === "medium") {
              // Continue transition: medium → high
              next[index!] = "high";
            } else if (current === "high") {
              // Turn off directly (no medium transition when turning off)
              next[index!] = "off";
            }
          }
        }
        return next;
      });
    }, 200); // 0.2s interval to match transition duration

    return () => clearInterval(interval);
  }, [isRandomLightsMode, motionOn, shouldReduceMotion, totalLights]);

  const isNextVariant = variant === "next";

  const CardContent = (
    <div
      ref={rootRef}
      data-reduced={shouldReduceMotion ? "true" : "false"}
      data-slot="switchboard-card"
      className={cn(
        "relative flex h-[380px] w-full flex-col overflow-hidden rounded-xl border p-6 transition-[border-color,background-color] duration-150",
        isNextVariant
          ? "border-0 dark:border-0 dark:shadow-[inset_0_0_6px_rgba(255,255,255,0.1)]"
          : "border-border bg-background hover:border-foreground/20",
        className
      )}
      data-variant={isNextVariant ? "next" : undefined}
      style={
        isNextVariant
          ? ({
              background:
                "linear-gradient(110deg, oklch(0.65 0 0) 0.06%, oklch(0.54 0 0) 100%)",
            } as React.CSSProperties)
          : undefined
      }
    >
      {/* Illustration/Switchboard */}
      <div
        className="flex h-full w-full items-center justify-center"
        data-illustration="true"
      >
        <div
          className="grid h-full w-full"
          style={{
            gap: `min(1px, calc(100% / ${columns} / 10))`,
            gridTemplateColumns: `repeat(${columns}, minmax(0, 1fr))`,
            gridTemplateRows: `repeat(${rows}, minmax(0, 1fr))`,
            maxHeight: "81px",
            transitionDuration: `${transitionDuration}ms`,
          }}
        >
          {lightStates.map((state, index) => (
            <LightBulb
              // biome-ignore lint/suspicious/noArrayIndexKey: Light grid position is stable and never reorders
              key={`light-${index}`}
              state={state}
              transitionDuration={transitionDuration}
            />
          ))}
        </div>
      </div>

      {/* Title */}
      <div className="mt-4 flex flex-row items-center justify-start gap-2 text-left">
        <h3
          className={cn(
            "text-left font-semibold leading-8 tracking-[-0.04em]",
            isNextVariant ? "mt-4 text-2xl" : "text-foreground text-xl"
          )}
          data-title="true"
          style={
            isNextVariant
              ? ({ color: "oklch(0.95 0 0)" } as React.CSSProperties)
              : undefined
          }
        >
          {title}
        </h3>
      </div>

      {/* Subtitle */}
      <p
        className={cn(
          "text-left text-sm leading-relaxed tracking-[-0.01em]",
          isNextVariant
            ? "mt-1 max-w-[80%] text-base"
            : "mt-1 text-foreground/70"
        )}
        data-subtitle="true"
        style={
          isNextVariant
            ? ({ color: "oklch(0.9 0 0)" } as React.CSSProperties)
            : undefined
        }
      >
        {subtitle}
      </p>
    </div>
  );

  if (href) {
    return (
      <a
        aria-label={title}
        className="focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        href={href}
      >
        {CardContent}
      </a>
    );
  }

  if (onButtonClick) {
    return (
      <button
        aria-label={title}
        className="cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
        onClick={onButtonClick}
        type="button"
      >
        {CardContent}
      </button>
    );
  }

  return CardContent;
}

function LightBulb({
  state,
  transitionDuration,
}: {
  state: LightState;
  transitionDuration: number;
}) {
  const transitionStyle = {
    transition: `opacity ${transitionDuration}ms ease-out, transform ${transitionDuration}ms ease-out`,
  };

  return (
    <div
      className={cn(
        "relative rounded-full",
        state === "off" && "bg-foreground/50",
        state === "high" ? "h-[2px] w-[2px]" : "h-px w-px"
      )}
      data-state={state}
      style={{
        ...transitionStyle,
        transform: state === "off" ? "unset" : "scale(1)",
      }}
    >
      {/* Glow effect for medium state (::before equivalent) */}
      {state === "medium" && (
        <div
          className="absolute inset-0 rounded-full"
          style={{
            ...transitionStyle,
            backgroundColor: "var(--color-brand)",
            boxShadow:
              "0 0 2px 1px color-mix(in oklch, var(--color-brand), transparent 60%), 0 0 4px 1.5px color-mix(in oklch, var(--color-brand), transparent 75%)",
            opacity: 1,
          }}
        />
      )}

      {/* Glow effect for high state (::after equivalent) */}
      {state === "high" && (
        <div
          className="absolute inset-0 rounded-full"
          style={{
            ...transitionStyle,
            backgroundColor: "var(--color-brand)",
            boxShadow:
              "0 0 2px 1px color-mix(in oklch, var(--color-brand), transparent 40%), 0 0 4px 1.5px color-mix(in oklch, var(--color-brand), transparent 65%), 0 0 6px 2px color-mix(in oklch, var(--color-brand), transparent 80%)",
            opacity: 1,
          }}
        />
      )}
    </div>
  );
}

"use client";

// Ported from kokonutUI (MIT) — https://github.com/kokonut-labs/kokonutui/blob/main/components/kokonutui/swoosh-text.tsx

/**
 * @author: @dorianbaffier
 * @description: Extruded Text
 * @version: 2.0.0
 * @date: 2026-10-14
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { type HTMLAttributes, type RefObject, useEffect, useRef } from "react";
import { useAnimationActive } from "@/hooks/use-animation-active";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { cn } from "@/lib/utils";

export interface SwooshTextProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  text?: string;
  /** Element to render, e.g. "h1" for a heading. */
  as?: "div" | "span" | "p" | "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
  /** Stacked layers behind each letter (clamped to 6-16). */
  depth?: number;
  /** Total extrusion length, in em. */
  length?: number;
  /** Optional color for the deepest layer only, e.g. "#f97316". */
  accent?: string;
}

// Spring for the light direction. Under-damped on purpose: a fast flick
// swings the extrusion past its target before it settles.
const LIGHT_STIFFNESS = 170;
const LIGHT_DAMPING = 13;
// How much of the pointer's velocity is carried into the spring.
const LIGHT_KICK = 9;
const LIGHT_MAX_SPEED = 30;
const LIGHT_MAX_LENGTH = 1.35;
// Spring for each keycap, close to critical so letters sink without wobble.
const KEY_STIFFNESS = 420;
const KEY_DAMPING = 34;
// How far a fully pressed key sinks into its extrusion (fraction of depth).
const MAX_SINK = 0.72;
// Falloff radius of the press wave, in multiples of the font size.
const PRESS_RADIUS = 0.75;
// Rest: light from the top-left, extrusion toward the bottom-right (45°).
const REST = Math.SQRT1_2;
const EPSILON = 0.0008;
const WHITESPACE = /\s+/;

const segmenter =
  typeof Intl !== "undefined" && "Segmenter" in Intl
    ? new Intl.Segmenter(undefined, { granularity: "grapheme" })
    : null;

/** Splits into user-perceived characters, so emoji and accents stay whole. */
function splitGraphemes(value: string): string[] {
  return segmenter
    ? Array.from(segmenter.segment(value), (s) => s.segment)
    : Array.from(value);
}

interface Key {
  x: number;
  y: number;
  p: number;
  v: number;
  // Layers deepest first, then the face (index 0) last.
  layers: HTMLSpanElement[];
  // Last value written, so unchanged keys are skipped.
  drawn: string;
}

interface Sim {
  lx: number;
  ly: number;
  vx: number;
  vy: number;
  tx: number;
  ty: number;
  // Pointer in client coordinates, or null when it is away.
  px: number | null;
  py: number | null;
  pressed: number;
  fontSize: number;
  depth: number;
  step: number;
  keys: Key[];
}

function round(value: number) {
  return Math.round(value * 10_000) / 10_000;
}

function clamp(value: number, max: number) {
  return Math.max(-max, Math.min(max, value));
}

function lightTarget(sim: Sim, rect: DOMRect): [number, number] {
  if (sim.px === null || sim.py === null) {
    return [REST, REST];
  }
  // The extrusion points away from the light (the pointer). Near the centre
  // the light is overhead, so the extrusion shortens instead of flipping.
  const dx = rect.left + rect.width / 2 - sim.px;
  const dy = rect.top + rect.height / 2 - sim.py;
  const reach = Math.max(Math.hypot(dx, dy), sim.fontSize * 0.9);
  return [dx / reach, dy / reach];
}

function stepLight(sim: Sim, dt: number) {
  sim.vx += ((sim.tx - sim.lx) * LIGHT_STIFFNESS - sim.vx * LIGHT_DAMPING) * dt;
  sim.vy += ((sim.ty - sim.ly) * LIGHT_STIFFNESS - sim.vy * LIGHT_DAMPING) * dt;
  sim.lx += sim.vx * dt;
  sim.ly += sim.vy * dt;
  // Keep a wild flick from stretching the extrusion too far.
  const length = Math.hypot(sim.lx, sim.ly);
  if (length > LIGHT_MAX_LENGTH) {
    sim.lx = (sim.lx / length) * LIGHT_MAX_LENGTH;
    sim.ly = (sim.ly / length) * LIGHT_MAX_LENGTH;
  }
  const moving =
    Math.abs(sim.tx - sim.lx) > EPSILON ||
    Math.abs(sim.ty - sim.ly) > EPSILON ||
    Math.hypot(sim.vx, sim.vy) > EPSILON;
  if (!moving) {
    sim.lx = sim.tx;
    sim.ly = sim.ty;
    sim.vx = 0;
    sim.vy = 0;
  }
  return moving;
}

function keyTarget(sim: Sim, index: number, dx: number, dy: number) {
  if (index === sim.pressed) {
    return 1;
  }
  if (sim.px === null) {
    return 0;
  }
  const distance = Math.hypot(dx, dy) / (sim.fontSize * PRESS_RADIUS);
  return distance > 2.5 ? 0 : Math.exp(-distance * distance);
}

function stepKeys(sim: Sim, dt: number, rect: DOMRect) {
  let moving = false;
  const x = (sim.px ?? 0) - rect.left;
  const y = (sim.py ?? 0) - rect.top;
  for (let i = 0; i < sim.keys.length; i++) {
    const key = sim.keys[i];
    const target = keyTarget(sim, i, x - key!.x, y - key!.y) * MAX_SINK;
    key!.v += ((target - key!.p) * KEY_STIFFNESS - key!.v * KEY_DAMPING) * dt;
    key!.p += key!.v * dt;
    if (Math.abs(target - key!.p) < EPSILON && Math.abs(key!.v) < EPSILON) {
      key!.p = target;
      key!.v = 0;
    } else {
      moving = true;
    }
  }
  return moving;
}

// Layer `index` sits `index` steps deep. As the key sinks (p → 1) the
// column compresses toward the deepest layer, which never moves.
function layerTransform(
  index: number,
  depth: number,
  step: number,
  light: [number, number],
  p: number
) {
  const offset = (index + (depth - index) * p) * step;
  return `translate3d(${round(light[0] * offset)}em, ${round(light[1] * offset)}em, 0)`;
}

// Writes transforms straight onto each layer. Changing a custom property on
// the root instead would restyle every descendant each frame (~10x slower).
function drawKeys(sim: Sim) {
  const light: [number, number] = [round(sim.lx), round(sim.ly)];
  for (const key of sim.keys) {
    const p = round(Math.max(0, key.p));
    const signature = `${light[0]},${light[1]},${p}`;
    if (signature === key.drawn) {
      continue;
    }
    key.drawn = signature;
    const count = key.layers.length;
    for (let j = 0; j < count; j++) {
      key.layers[j]!.style.transform = layerTransform(
        count - 1 - j,
        sim.depth,
        sim.step,
        light,
        p
      );
    }
  }
}

const REST_LIGHT: [number, number] = [REST, REST];

function layerColor(index: number, depth: number, accent?: string) {
  if (index === depth && accent) {
    return accent;
  }
  const t = Math.round(((index - 1) / Math.max(1, depth - 1)) * 100);
  return `color-mix(in oklab, var(--ex-far) ${t}%, var(--ex-near))`;
}

function Letter({
  char,
  depth,
  step,
  accent,
}: {
  char: string;
  depth: number;
  step: number;
  accent?: string;
}) {
  // Deepest layer first so the face paints on top.
  const layers = Array.from({ length: depth }, (_, i) => depth - i);
  return (
    <span className="relative inline-block" data-key="">
      {layers.map((i) => (
        <span
          className="absolute inset-0"
          key={i}
          style={{
            color: layerColor(i, depth, accent),
            transform: layerTransform(i, depth, step, REST_LIGHT, 0),
          }}
        >
          {char}
        </span>
      ))}
      <span
        className="relative inline-block text-[var(--ex-face)]"
        style={{ transform: layerTransform(0, depth, step, REST_LIGHT, 0) }}
      >
        {char}
      </span>
    </span>
  );
}

function measureKeys(root: HTMLElement, sim: Sim) {
  const rect = root.getBoundingClientRect();
  sim.fontSize = Number.parseFloat(getComputedStyle(root).fontSize) || 16;
  const els = root.querySelectorAll<HTMLSpanElement>("[data-key]");
  sim.keys = Array.from(els, (el, i) => {
    const r = el.getBoundingClientRect();
    const previous = sim.keys[i];
    return {
      layers: Array.from(el.children) as HTMLSpanElement[],
      drawn: "",
      x: r.left - rect.left + r.width / 2,
      y: r.top - rect.top + r.height / 2,
      p: previous?.p ?? 0,
      v: previous?.v ?? 0,
    };
  });
}

function nearestKey(sim: Sim, x: number, y: number) {
  let best = -1;
  let bestDistance = sim.fontSize * 0.8;
  for (let i = 0; i < sim.keys.length; i++) {
    const d = Math.hypot(sim.keys[i]!.x - x, sim.keys[i]!.y - y);
    if (d < bestDistance) {
      best = i;
      bestDistance = d;
    }
  }
  return best;
}

function createSim(depth: number, step: number): Sim {
  return {
    lx: REST,
    ly: REST,
    vx: 0,
    vy: 0,
    tx: REST,
    ty: REST,
    px: null,
    py: null,
    pressed: -1,
    fontSize: 16,
    depth,
    step,
    keys: [],
  };
}

function useExtrusion(
  rootRef: RefObject<HTMLElement | null>,
  text: string,
  depth: number,
  step: number
) {
  const motionOn = useAnimationActive(rootRef);
  const prefersReduced = usePrefersReducedMotion();
  const motionOnRef = useRef(false);
  const reducedRef = useRef(false);
  const resumeRef = useRef<() => void>(() => {});
  useEffect(() => {
    motionOnRef.current = motionOn;
    reducedRef.current = prefersReduced;
    resumeRef.current();
  }, [motionOn, prefersReduced]);
  useEffect(() => {
    const root = rootRef.current;
    // `text` is read so the effect re-runs (and re-measures) when it changes.
    if (!root || text === "") {
      return;
    }
    // Reduced motion keeps the fixed 45° extrusion from the first render.
    if (reducedRef.current) {
      return;
    }

    const sim = createSim(depth, step);
    let frame = 0;
    let last = 0;
    let visible = false;

    const tick = (now: number) => {
      frame = 0;
      if (!motionOnRef.current) {
        last = 0;
        return;
      }
      const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60;
      last = now;
      const rect = root.getBoundingClientRect();
      [sim.tx, sim.ty] = lightTarget(sim, rect);
      const lightMoving = stepLight(sim, dt);
      const keysMoving = stepKeys(sim, dt, rect);
      drawKeys(sim);
      // Sleep once everything has settled, or while offscreen.
      if ((lightMoving || keysMoving) && visible && motionOnRef.current) {
        frame = requestAnimationFrame(tick);
      } else {
        last = 0;
      }
    };

    const wake = () => {
      if (!frame && visible && motionOnRef.current) {
        frame = requestAnimationFrame(tick);
      }
    };

    const onMove = (event: PointerEvent) => {
      if (!visible) {
        return;
      }
      const rect = root.getBoundingClientRect();
      const [ax, ay] = lightTarget(sim, rect);
      sim.px = event.clientX;
      sim.py = event.clientY;
      const [bx, by] = lightTarget(sim, rect);
      // Carry the pointer's velocity into the spring so a flick swings it.
      sim.vx = clamp(sim.vx + (bx - ax) * LIGHT_KICK, LIGHT_MAX_SPEED);
      sim.vy = clamp(sim.vy + (by - ay) * LIGHT_KICK, LIGHT_MAX_SPEED);
      wake();
    };

    const onLeave = () => {
      sim.px = null;
      sim.py = null;
      sim.pressed = -1;
      wake();
    };

    const onDown = (event: PointerEvent) => {
      const rect = root.getBoundingClientRect();
      sim.pressed = nearestKey(
        sim,
        event.clientX - rect.left,
        event.clientY - rect.top
      );
      sim.px = event.clientX;
      sim.py = event.clientY;
      wake();
    };

    const onUp = (event: PointerEvent) => {
      sim.pressed = -1;
      // Touch has no hover: once the finger lifts, the light goes home.
      if (event.pointerType !== "mouse") {
        sim.px = null;
        sim.py = null;
      }
      wake();
    };

    let onScreen = false;
    const syncVisible = () => {
      visible = onScreen && motionOnRef.current;
      if (!visible && frame) {
        cancelAnimationFrame(frame);
        frame = 0;
        last = 0;
      }
      if (visible) {
        wake();
      }
    };
    resumeRef.current = syncVisible;

    const measure = () => measureKeys(root, sim);
    measure();
    const resize = new ResizeObserver(measure);
    resize.observe(root);
    document.fonts?.ready.then(measure).catch(() => undefined);

    const intersection = new IntersectionObserver(([entry]) => {
      onScreen = entry!.isIntersecting;
      syncVisible();
    });
    intersection.observe(root);

    window.addEventListener("pointermove", onMove, { passive: true });
    document.documentElement.addEventListener("pointerleave", onLeave);
    root.addEventListener("pointerdown", onDown);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);

    return () => {
      cancelAnimationFrame(frame);
      resize.disconnect();
      intersection.disconnect();
      window.removeEventListener("pointermove", onMove);
      document.documentElement.removeEventListener("pointerleave", onLeave);
      root.removeEventListener("pointerdown", onDown);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
      resumeRef.current = () => {};
    };
  }, [rootRef, text, depth, step]);
}

function SwooshText({
  text = "Extruded",
  as: Tag = "div",
  depth = 12,
  length = 0.2,
  accent,
  className,
  style,
  ...props
}: SwooshTextProps) {
  const rootRef = useRef<HTMLElement | null>(null);
  const prefersReduced = usePrefersReducedMotion();
  const layers = Math.round(Math.min(16, Math.max(6, depth)));
  const step = length / layers;
  useExtrusion(rootRef, text, layers, step);

  const words = text.split(WHITESPACE).filter(Boolean);

  return (
    <Tag
      data-slot="swoosh-text"
      data-reduced={prefersReduced ? "true" : "false"}
      className={cn(
        "relative touch-manipulation select-none font-bold text-5xl tracking-tight",
        "[--ex-face:var(--color-zinc-900)] [--ex-far:var(--color-zinc-600)] [--ex-near:var(--color-zinc-300)]",
        "dark:[--ex-face:var(--color-zinc-50)] dark:[--ex-far:var(--color-zinc-700)] dark:[--ex-near:var(--color-zinc-400)]",
        className
      )}
      ref={(node: HTMLElement | null) => {
        rootRef.current = node;
      }}
      style={style}
      {...props}
    >
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">
        {words.map((word, w) => (
          // biome-ignore lint/suspicious/noArrayIndexKey: words can repeat
          <span key={w}>
            {w > 0 ? " " : null}
            <span className="inline-block whitespace-nowrap">
              {splitGraphemes(word).map((char, c) => (
                <Letter
                  accent={accent}
                  char={char}
                  depth={layers}
                  // biome-ignore lint/suspicious/noArrayIndexKey: letters repeat
                  key={c}
                  step={step}
                />
              ))}
            </span>
          </span>
        ))}
      </span>
    </Tag>
  );
}

export { SwooshText }

"use client";

// Ported from kokonutUI (MIT) — https://github.com/kokonut-labs/kokonutui/blob/main/components/kokonutui/synced-transcript.tsx

/**
 * @author: @dorianbaffier
 * @description: Synced Transcript
 * @version: 1.0.0
 * @date: 2026-10-16
 * @license: MIT
 * @website: https://kokonutui.com
 * @github: https://github.com/kokonut-labs/kokonutui
 */

import { ArrowDown, ArrowUp, Pause, Play } from "lucide-react";
import {
  type KeyboardEvent,
  type MouseEvent,
  memo,
  type PointerEvent,
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { useAnimationActive } from "@/hooks/use-animation-active";
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { cn } from "@/lib/utils";

const SPEEDS = [1, 1.5, 2];
const WHITESPACE = /\s+/;

export interface TranscriptSegment {
  speaker: string;
  /** Seconds from the start. */
  start: number;
  end: number;
  text: string;
}

export interface SyncedTranscriptProps {
  title?: string;
  segments?: TranscriptSegment[];
  /** Seconds. Defaults to the end of the last segment. Playback is simulated; drive it from your own audio with `onTimeChange`. */
  duration?: number;
  onTimeChange?: (seconds: number) => void;
  className?: string;
}

interface Word {
  text: string;
  start: number;
  /** Index across the whole transcript. */
  index: number;
}

// Times each segment from its word count, with a breath between speakers.
function timed(lines: [string, string][]): TranscriptSegment[] {
  const out: TranscriptSegment[] = [];
  let t = 0.6;
  for (const [speaker, text] of lines) {
    const words = text.split(WHITESPACE).length;
    const end = t + words / 2.7;
    out.push({ speaker, start: t, end, text });
    t = end + 0.7;
  }
  return out;
}

const DEFAULT_SEGMENTS = timed([
  [
    "Maya",
    "Welcome back. Today we're talking about the small details in interfaces, the ones nobody notices until they're missing.",
  ],
  [
    "Theo",
    "Right. Like a menu that opens in a hundred and fifty milliseconds instead of four hundred. You never think about it, but the slow one feels broken.",
  ],
  ["Maya", "So where do you start when something feels off?"],
  [
    "Theo",
    "I slow it down. I record the screen and step through it frame by frame. Most of the time the easing is wrong, or two things move that should move as one.",
  ],
  ["Maya", "And when it finally feels right?"],
  [
    "Theo",
    "Then I stop touching it. The best motion is the kind you only miss when it's gone.",
  ],
]);

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(hi, Math.max(lo, v));

function formatTime(seconds: number) {
  const s = Math.max(0, Math.floor(seconds));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
}

// Spreads a segment's time over its words by length, so long words last longer.
function splitWords(segments: TranscriptSegment[]) {
  let index = 0;
  return segments.map((segment) => {
    const parts = segment.text.split(WHITESPACE).filter(Boolean);
    const total = parts.reduce((sum, w) => sum + w.length + 1, 0);
    let t = segment.start;
    return parts.map((text) => {
      const word = { text, start: t, index };
      t += ((text.length + 1) / total) * (segment.end - segment.start);
      index += 1;
      return word;
    });
  });
}

// What each paragraph needs to know: all spoken, none yet, or which word.
// Past and future paragraphs get a constant, so they skip re-rendering.
function paragraphActive(segment: number, current: number, active: number) {
  if (segment < current) {
    return Number.MAX_SAFE_INTEGER;
  }
  return segment === current ? active : -1;
}

// Only the paragraph holding the spoken word re-renders as time moves.
const Paragraph = memo(function Paragraph({
  words,
  active,
}: {
  words: Word[];
  /** The spoken word's global index. */
  active: number;
}) {
  return (
    <>
      {words.map((word) => (
        <span
          className={cn(
            "transition-colors duration-150 ease-out",
            word.index <= active
              ? "text-zinc-900 dark:text-zinc-100"
              : "text-zinc-400 dark:text-zinc-500"
          )}
          data-index={word.index}
          key={word.index}
        >
          {word.text}{" "}
        </span>
      ))}
    </>
  );
});

function SyncedTranscript({
  title = "Frame Rate · Episode 48",
  segments = DEFAULT_SEGMENTS,
  duration: durationProp,
  onTimeChange,
  className,
}: SyncedTranscriptProps) {
  const duration = durationProp ?? Math.ceil((segments.at(-1)?.end ?? 0) + 0.6);
  const words = useMemo(() => splitWords(segments), [segments]);
  const flat = useMemo(() => words.flat(), [words]);

  const [time, setTime] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [speedIndex, setSpeedIndex] = useState(0);
  const [following, setFollowing] = useState(true);
  // Where the spoken word is when the reader has scrolled away from it.
  const [away, setAway] = useState<"up" | "down" | null>(null);
  const timeRef = useRef(0);
  const scrollRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(scrollRef);
  const prefersReduced = usePrefersReducedMotion();
  const motionOnRef = useRef(false);
  const reducedRef = useRef(false);
  const resumeRef = useRef<() => void>(() => {});
  useEffect(() => {
    motionOnRef.current = motionOn;
    reducedRef.current = prefersReduced;
    resumeRef.current();
  }, [motionOn, prefersReduced]);
  const contentRef = useRef<HTMLDivElement>(null);
  const markRef = useRef<HTMLDivElement>(null);
  const lastTop = useRef<number | null>(null);
  const rate = SPEEDS[speedIndex] ?? 1;

  useEffect(() => {
    if (!playing) {
      resumeRef.current = () => {};
      return;
    }
    let frame = 0;
    let last = 0;
    const tick = (now: number) => {
      frame = 0;
      if (!motionOnRef.current) {
        last = 0;
        return;
      }
      const next = Math.min(
        duration,
        timeRef.current + (last ? ((now - last) / 1000) * rate : 0)
      );
      last = now;
      timeRef.current = next;
      setTime(next);
      if (next >= duration) {
        setPlaying(false);
        return;
      }
      frame = requestAnimationFrame(tick);
    };
    const kick = () => {
      if (motionOnRef.current && !frame) {
        last = 0;
        frame = requestAnimationFrame(tick);
      }
    };
    resumeRef.current = kick;
    kick();
    return () => {
      resumeRef.current = () => {};
      cancelAnimationFrame(frame);
    };
  }, [playing, duration, rate]);

  useEffect(() => {
    onTimeChange?.(time);
  }, [time, onTimeChange]);

  const seek = useCallback(
    (seconds: number) => {
      const next = clamp(seconds, 0, duration);
      timeRef.current = next;
      setTime(next);
    },
    [duration]
  );

  // The last word that has started, or -1 before the first.
  let active = -1;
  for (const word of flat) {
    if (word.start <= time) {
      active = word.index;
    } else {
      break;
    }
  }
  const activeSegment = words.findIndex((ws) =>
    ws.some((w) => w.index === active)
  );

  const scrollToWord = useCallback((el: HTMLElement, smooth: boolean) => {
    const box = scrollRef.current;
    if (!box) {
      return;
    }
    // Keep the spoken line a third of the way down, like lyrics.
    const top =
      box.scrollTop +
      el.getBoundingClientRect().top -
      box.getBoundingClientRect().top -
      box.clientHeight / 3;
    box.scrollTo({
      top,
      behavior: smooth && !prefersReduced ? "smooth" : "auto",
    });
  }, [prefersReduced]);

  // One highlight slides from word to word; it jumps, unanimated, to a new line.
  useLayoutEffect(() => {
    const mark = markRef.current;
    const el = contentRef.current?.querySelector<HTMLElement>(
      `[data-index="${active}"]`
    );
    if (!(mark && el)) {
      if (mark) {
        mark.style.opacity = "0";
      }
      lastTop.current = null;
      return;
    }
    const sameLine = lastTop.current === el.offsetTop;
    mark.style.transition = sameLine
      ? "transform 140ms cubic-bezier(0.23, 1, 0.32, 1), width 140ms cubic-bezier(0.23, 1, 0.32, 1), opacity 150ms ease-out"
      : "opacity 150ms ease-out";
    // The trailing space is part of the span; leave it out of the mark.
    const space = Number.parseFloat(getComputedStyle(el).fontSize) * 0.28;
    mark.style.transform = `translate(${el.offsetLeft - 3}px, ${el.offsetTop}px)`;
    mark.style.width = `${el.offsetWidth - space + 6}px`;
    mark.style.height = `${el.offsetHeight}px`;
    mark.style.opacity = "1";
    if (!sameLine && following) {
      scrollToWord(el, lastTop.current !== null);
    }
    lastTop.current = el.offsetTop;
  }, [active, following, scrollToWord]);

  // When the reader scrolls away, note which way the spoken word went.
  const checkAway = useCallback(() => {
    const box = scrollRef.current;
    const el = contentRef.current?.querySelector<HTMLElement>(
      `[data-index="${active}"]`
    );
    if (!(box && el) || following) {
      setAway(null);
      return;
    }
    const word = el.getBoundingClientRect();
    const view = box.getBoundingClientRect();
    if (word.bottom < view.top) {
      setAway("up");
    } else if (word.top > view.bottom) {
      setAway("down");
    } else {
      setAway(null);
    }
  }, [active, following]);

  useEffect(() => {
    checkAway();
  }, [checkAway]);

  const takeOver = () => setFollowing(false);

  const follow = () => {
    setFollowing(true);
    setAway(null);
    const el = contentRef.current?.querySelector<HTMLElement>(
      `[data-index="${active}"]`
    );
    if (el) {
      scrollToWord(el, true);
    }
  };

  const handleWordClick =
    (segment: TranscriptSegment) => (event: MouseEvent<HTMLButtonElement>) => {
      const target = (event.target as HTMLElement).closest("[data-index]");
      const index = Number(target?.getAttribute("data-index") ?? -1);
      // Keyboard presses have no word under them; start the paragraph.
      seek(index >= 0 ? (flat[index]?.start ?? segment.start) : segment.start);
      setFollowing(true);
    };

  const handleProgress = (event: PointerEvent<HTMLDivElement>) => {
    if (event.type === "pointerdown") {
      event.currentTarget.setPointerCapture(event.pointerId);
    } else if (!event.currentTarget.hasPointerCapture(event.pointerId)) {
      return;
    }
    const rect = event.currentTarget.getBoundingClientRect();
    seek(((event.clientX - rect.left) / rect.width) * duration);
    setFollowing(true);
  };

  const handleProgressKey = (event: KeyboardEvent<HTMLDivElement>) => {
    const moves: Record<string, number> = {
      ArrowLeft: -5,
      ArrowDown: -5,
      ArrowRight: 5,
      ArrowUp: 5,
      Home: -duration,
      End: duration,
    };
    if (event.key === " ") {
      event.preventDefault();
      setPlaying((p) => !p);
      return;
    }
    const move = moves[event.key];
    if (move !== undefined) {
      event.preventDefault();
      seek(time + move);
      setFollowing(true);
    }
  };

  const togglePlay = () => {
    if (!playing && timeRef.current >= duration) {
      seek(0);
    }
    setPlaying((p) => !p);
  };

  return (
    <div
      data-slot="synced-transcript"
      data-reduced={prefersReduced ? "true" : "false"}
      className={cn(
        "w-full max-w-md select-none rounded-3xl border border-zinc-200 bg-white text-zinc-900 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-100",
        className
      )}
    >
      <div className="flex items-center justify-between gap-3 px-5 pt-5">
        <div className="min-w-0">
          <p className="text-xs text-zinc-500 dark:text-zinc-400">Transcript</p>
          <p className="truncate font-medium text-sm">{title}</p>
        </div>
        <button
          aria-label={`Playback speed ${rate}x`}
          className="h-7 shrink-0 rounded-full border border-zinc-200 px-2.5 font-medium text-xs tabular-nums outline-none transition-colors duration-150 ease-out hover:bg-zinc-100 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:border-zinc-800 dark:hover:bg-zinc-900"
          onClick={() => setSpeedIndex((i) => (i + 1) % SPEEDS.length)}
          type="button"
        >
          {rate}×
        </button>
      </div>

      <div className="relative">
        <section
          aria-label="Transcript"
          className="h-72 overflow-y-auto px-5 py-6 outline-none [mask-image:linear-gradient(to_bottom,transparent,black_24px,black_calc(100%-24px),transparent)] focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-inset"
          onScroll={checkAway}
          onTouchMove={takeOver}
          onWheel={takeOver}
          ref={scrollRef}
        >
          <div className="relative isolate" ref={contentRef}>
            <div
              aria-hidden
              className="pointer-events-none absolute top-0 left-0 -z-10 rounded-md bg-zinc-100 opacity-0 dark:bg-zinc-800/80"
              ref={markRef}
            />
            {segments.map((segment, i) => (
              <div
                className={cn(i > 0 && "mt-5")}
                key={`${segment.start}-${segment.speaker}`}
              >
                <div className="mb-1 flex items-center gap-2 text-xs">
                  <span
                    aria-hidden
                    className="flex size-5 items-center justify-center rounded-full bg-zinc-100 font-medium text-[10px] text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300"
                  >
                    {segment.speaker.charAt(0)}
                  </span>
                  <span className="font-medium">{segment.speaker}</span>
                  <button
                    aria-label={`Play from ${formatTime(segment.start)}`}
                    className="rounded text-zinc-400 tabular-nums outline-none transition-colors duration-150 ease-out hover:text-zinc-900 focus-visible:ring-2 focus-visible:ring-zinc-400 dark:text-zinc-500 dark:hover:text-zinc-100"
                    onClick={() => {
                      seek(segment.start);
                      setFollowing(true);
                    }}
                    type="button"
                  >
                    {formatTime(segment.start)}
                  </button>
                </div>
                <button
                  className="block cursor-pointer rounded-sm text-left text-[15px] leading-7 outline-none focus-visible:ring-2 focus-visible:ring-zinc-400"
                  onClick={handleWordClick(segment)}
                  tabIndex={-1}
                  type="button"
                >
                  <Paragraph
                    active={paragraphActive(i, activeSegment, active)}
                    words={words[i] ?? []}
                  />
                </button>
              </div>
            ))}
          </div>
        </section>

        {/* Back to the spoken word after scrolling away. */}
        <button
          className={cn(
            "absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-1.5 rounded-full bg-zinc-900 px-3 py-1.5 font-medium text-white text-xs shadow-sm outline-none transition-[opacity,translate] duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] focus-visible:ring-2 focus-visible:ring-zinc-400 dark:bg-zinc-100 dark:text-zinc-900",
            away
              ? "translate-y-0 opacity-100"
              : "pointer-events-none translate-y-2 opacity-0"
          )}
          onClick={follow}
          tabIndex={away ? 0 : -1}
          type="button"
        >
          {away === "up" ? (
            <ArrowUp aria-hidden className="size-3.5" />
          ) : (
            <ArrowDown aria-hidden className="size-3.5" />
          )}
          Back to now
        </button>
      </div>

      <div className="flex items-center gap-3 border-zinc-200 border-t px-5 py-3 dark:border-zinc-800">
        <button
          aria-label={playing ? "Pause" : "Play"}
          className="flex size-9 shrink-0 items-center justify-center rounded-full bg-zinc-900 text-white outline-none transition-colors duration-150 ease-out hover:bg-zinc-700 focus-visible:ring-2 focus-visible:ring-zinc-400 focus-visible:ring-offset-2 dark:bg-zinc-100 dark:text-zinc-900 dark:focus-visible:ring-offset-zinc-950 dark:hover:bg-zinc-300"
          onClick={togglePlay}
          type="button"
        >
          {playing ? (
            <Pause aria-hidden className="size-4" fill="currentColor" />
          ) : (
            <Play
              aria-hidden
              className="size-4 translate-x-px"
              fill="currentColor"
            />
          )}
        </button>
        <span className="w-9 text-xs text-zinc-500 tabular-nums dark:text-zinc-400">
          {formatTime(time)}
        </span>
        <div
          aria-label="Seek"
          aria-valuemax={Math.round(duration)}
          aria-valuemin={0}
          aria-valuenow={Math.round(time)}
          aria-valuetext={`${formatTime(time)} of ${formatTime(duration)}`}
          className="group relative flex h-6 flex-1 cursor-pointer touch-none items-center rounded outline-none focus-visible:ring-2 focus-visible:ring-zinc-400"
          onKeyDown={handleProgressKey}
          onPointerDown={handleProgress}
          onPointerMove={handleProgress}
          role="slider"
          tabIndex={0}
        >
          <div className="h-1 w-full overflow-hidden rounded-full bg-zinc-200 dark:bg-zinc-800">
            <div
              className="h-full w-full origin-left rounded-full bg-zinc-900 dark:bg-zinc-100"
              style={{ transform: `scaleX(${time / duration})` }}
            />
          </div>
        </div>
        <span className="w-9 text-right text-xs text-zinc-500 tabular-nums dark:text-zinc-400">
          {formatTime(duration)}
        </span>
      </div>
    </div>
  );
}

