// Ported from uselayouts (MIT, (c) 2025 Urvish Mali) — https://github.com/iurvish/uselayouts/blob/main/registry/default/example/tactile-button.tsx

import { useState, type ReactNode } from "react"
import { motion } from "motion/react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

type Bulk = "sm" | "default" | "lg"
type Led = "blue" | "green" | "amber" | "red" | "slate"

const ledColor: Record<Led, string> = {
  blue: "var(--primary)",
  green: "var(--primary)",
  amber: "var(--accent)",
  red: "var(--destructive)",
  slate: "var(--muted-foreground)",
}

const bulkClass: Record<Bulk, { box: string; y: number; rotate: number }> = {
  sm: { box: "min-h-11 min-w-[130px] px-3.5 py-1.5 text-sm", y: -8, rotate: -7.5 },
  default: { box: "min-h-14 min-w-[176px] px-5 py-2 text-lg", y: -12, rotate: -8.5 },
  lg: { box: "min-h-[72px] min-w-[210px] px-7 py-3 text-2xl", y: -15, rotate: -8.8 },
}

export interface TactileRockerProps {
  children?: ReactNode
  pressed?: boolean
  defaultPressed?: boolean
  onPressedChange?: (pressed: boolean) => void
  showIndicator?: boolean
  indicatorColor?: Led
  bulk?: Bulk
  fullWidth?: boolean
  className?: string
}

export function TactileRocker({
  children = "Get Started",
  pressed,
  defaultPressed = false,
  onPressedChange,
  showIndicator = true,
  indicatorColor = "blue",
  bulk = "default",
  fullWidth = false,
  className,
}: TactileRockerProps) {
  const reduced = usePrefersReducedMotion()
  const [internal, setInternal] = useState(defaultPressed)
  const [holding, setHolding] = useState(false)
  const on = pressed ?? internal
  const down = on || holding
  const metrics = bulkClass[bulk]
  const spring = reduced ? { duration: 0 } : { type: "spring" as const, bounce: 0.45, duration: 0.55 }

  const toggle = () => {
    const next = !on
    if (pressed === undefined) setInternal(next)
    onPressedChange?.(next)
  }

  return (
    <div className={cn("relative inline-flex items-center justify-center", fullWidth && "w-full", className)}>
      <motion.span
        aria-hidden="true"
        className="absolute inset-1 rounded-2xl bg-[var(--muted)]"
        animate={{
          boxShadow: down
            ? "inset 0 2px 4px color-mix(in srgb, var(--foreground) 35%, transparent)"
            : "inset 0 1px 2px color-mix(in srgb, var(--foreground) 20%, transparent)",
        }}
        transition={spring}
      />
      <motion.button
        type="button"
        aria-pressed={on}
        data-pressed={on ? "true" : "false"}
        onPointerDown={() => setHolding(true)}
        onPointerUp={() => setHolding(false)}
        onPointerCancel={() => setHolding(false)}
        onPointerLeave={() => setHolding(false)}
        onClick={toggle}
        className={cn(
          "relative z-10 flex items-center justify-center gap-3 rounded-2xl border border-[var(--background)] bg-[var(--card)] font-medium text-[var(--foreground)] shadow-md focus-visible:ring-2 focus-visible:ring-[var(--ring)] focus-visible:outline-none motion-reduce:transform-none",
          metrics.box,
          fullWidth && "w-full",
        )}
        animate={{
          rotate: reduced ? 0 : down ? metrics.rotate : 0,
          y: reduced ? 0 : down ? metrics.y : 0,
          x: reduced ? 0 : down ? 3 : 0,
        }}
        transition={spring}
      >
        {showIndicator ? (
          <motion.span
            aria-hidden="true"
            className="size-3 rounded-full"
            animate={{ backgroundColor: down ? ledColor[indicatorColor] : "var(--muted)" }}
            transition={spring}
          />
        ) : null}
        <span>{children}</span>
      </motion.button>
    </div>
  )
}

export default TactileRocker

// @vitest-environment jsdom

import { afterEach, beforeEach, expect, test, vi } from "vitest"
import { act, cleanup, fireEvent, render, screen } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"
import Matter from "matter-js"

import { TagJar } from "./tag-jar"

let reduceMotion = false
let now = 0
let rafId = 0
const queue = new Map<number, FrameRequestCallback>()
let createSpy: ReturnType<typeof vi.spyOn>

beforeEach(() => {
  reduceMotion = false
  now = 0
  rafId = 0
  queue.clear()
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: query.includes("prefers-reduced-motion") ? reduceMotion : false,
    media: query,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
    dispatchEvent() {
      return false
    },
  }))
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
    rafId += 1
    queue.set(rafId, cb)
    return rafId
  })
  vi.stubGlobal("cancelAnimationFrame", (handle: number) => {
    queue.delete(handle)
  })
  createSpy = vi.spyOn(Matter.Engine, "create")
})

afterEach(() => {
  cleanup()
  createSpy.mockRestore()
  vi.unstubAllGlobals()
})

function pump(steps: number) {
  act(() => {
    for (let i = 0; i < steps; i += 1) {
      const next = queue.entries().next().value as [number, FrameRequestCallback] | undefined
      if (!next) break
      queue.delete(next[0])
      now += 32
      next[1](now)
    }
  })
}

function jar() {
  return screen.getByRole("application", { name: "标签罐" })
}

test("默认把标签放进罐子，颜色跟随主题，不标记减弱动效", () => {
  render(<TagJar />)
  expect(screen.getByText("设计")).toBeInTheDocument()
  expect(screen.getByText("动效")).toBeInTheDocument()
  expect(screen.getByText("字体")).toBeInTheDocument()
  expect(screen.getByText("配色")).toBeInTheDocument()
  expect(screen.getByText("设计")).toHaveStyle({ backgroundColor: "var(--primary)" })
  expect(document.querySelector("[data-slot='tag-jar']")).not.toHaveAttribute("data-reduced")
  expect(createSpy).toHaveBeenCalled()
})

test("落下几帧后标签离开出生点", () => {
  render(<TagJar />)
  const tag = screen.getByText("设计")
  expect(tag.style.transform).toBe("")
  pump(6)
  expect(tag.style.transform).toContain("translate")
  expect(tag.style.transform).toContain("rotate")
})

test("拖动罐子会摇晃并回调", () => {
  const onShake = vi.fn()
  render(<TagJar onShake={onShake} />)
  fireEvent.pointerDown(jar(), { clientX: 0, clientY: 0, pointerId: 1, pointerType: "mouse" })
  fireEvent.pointerMove(jar(), { clientX: 28, clientY: 6, pointerId: 1, pointerType: "mouse" })
  fireEvent.pointerUp(jar(), { clientX: 28, clientY: 6, pointerId: 1, pointerType: "mouse" })
  expect(onShake).toHaveBeenCalledTimes(1)
  expect(jar()).toHaveAttribute("data-shaken", "true")
})

test("方向键摇晃罐子并回调", () => {
  const onShake = vi.fn()
  render(<TagJar onShake={onShake} />)
  fireEvent.keyDown(jar(), { key: "ArrowRight" })
  expect(onShake).toHaveBeenCalledTimes(1)
  expect(jar()).toHaveAttribute("data-shaken", "true")
})

test("触屏拖动能摇晃，不依赖悬停", () => {
  const onShake = vi.fn()
  render(<TagJar onShake={onShake} />)
  fireEvent.pointerDown(jar(), { clientX: 4, clientY: 4, pointerId: 2, pointerType: "touch" })
  fireEvent.pointerUp(jar(), { clientX: 36, clientY: 8, pointerId: 2, pointerType: "touch" })
  expect(onShake).toHaveBeenCalledTimes(1)
})

test("减弱动效时标签静静堆着，不创建引擎也不申请动画帧", () => {
  reduceMotion = true
  const onShake = vi.fn()
  render(<TagJar onShake={onShake} />)
  const root = document.querySelector("[data-slot='tag-jar']")
  const tag = screen.getByText("设计")
  const before = tag.style.left
  expect(root).toHaveAttribute("data-reduced", "true")
  expect(root).not.toHaveAttribute("data-physics")
  expect(tag.style.transform).toBe("")
  fireEvent.keyDown(jar(), { key: "ArrowRight" })
  pump(4)
  expect(onShake).toHaveBeenCalledTimes(1)
  expect(tag.style.left).not.toBe(before)
  expect(createSpy).not.toHaveBeenCalled()
  expect(queue.size).toBe(0)
})

