import { afterEach, beforeEach, expect, test, vi } from "vitest"
import { act, cleanup, fireEvent, render, screen } from "@testing-library/react"
import "@testing-library/jest-dom/vitest"

import { TossToTrash } from "./toss-to-trash"

let reduceMotion = false
let now = 0
let rafId = 0
const queue = new Map<number, FrameRequestCallback>()

beforeEach(() => {
  reduceMotion = false
  now = 0
  rafId = 0
  queue.clear()
  vi.stubGlobal("matchMedia", (query: string) => ({
    matches: query.includes("prefers-reduced-motion") ? reduceMotion : false,
    media: query,
    addEventListener() {},
    removeEventListener() {},
    addListener() {},
    removeListener() {},
    dispatchEvent() {
      return false
    },
  }))
  vi.stubGlobal("requestAnimationFrame", (cb: FrameRequestCallback) => {
    rafId += 1
    queue.set(rafId, cb)
    return rafId
  })
  vi.stubGlobal("cancelAnimationFrame", (handle: number) => {
    queue.delete(handle)
  })
})

afterEach(() => {
  cleanup()
  vi.unstubAllGlobals()
})

function pump(steps: number) {
  act(() => {
    for (let i = 0; i < steps; i += 1) {
      const next = queue.entries().next().value as [number, FrameRequestCallback] | undefined
      if (!next) break
      queue.delete(next[0])
      now += 32
      next[1](now)
    }
  })
}

function row(name: string) {
  return screen.getByRole("button", { name })
}

test("默认有三条和垃圾桶", () => {
  render(<TossToTrash />)
  expect(row("旧稿")).toBeInTheDocument()
  expect(row("重复")).toBeInTheDocument()
  expect(row("过期")).toBeInTheDocument()
  expect(screen.getByLabelText("垃圾桶")).toBeInTheDocument()
})

test("向下拖过阈值后沿抛物线落入，结束时删除并回调", () => {
  const onDelete = vi.fn()
  render(<TossToTrash onDelete={onDelete} />)
  const item = row("旧稿")
  fireEvent.pointerDown(item, { clientX: 10, clientY: 10, pointerId: 1, timeStamp: 0 })
  fireEvent.pointerMove(item, { clientX: 12, clientY: 100, pointerId: 1, timeStamp: 30 })
  fireEvent.pointerUp(item, { clientX: 12, clientY: 100, pointerId: 1, timeStamp: 40 })
  expect(onDelete).not.toHaveBeenCalled()
  expect(item.style.transform).toContain("translate")
  pump(24)
  expect(onDelete).toHaveBeenCalledWith("old")
  expect(screen.queryByRole("button", { name: "旧稿" })).toBeNull()
})

test("拖得不够远时条目回到原处", () => {
  const onDelete = vi.fn()
  render(<TossToTrash onDelete={onDelete} />)
  const item = row("重复")
  fireEvent.pointerDown(item, { clientX: 0, clientY: 0, pointerId: 1, timeStamp: 0 })
  fireEvent.pointerUp(item, { clientX: 8, clientY: 20, pointerId: 1, timeStamp: 40 })
  pump(8)
  expect(onDelete).not.toHaveBeenCalled()
  expect(row("重复")).toBeInTheDocument()
  expect(queue.size).toBe(0)
})

test("Delete 键把焦点条目抛进垃圾桶", () => {
  const onDelete = vi.fn()
  render(<TossToTrash onDelete={onDelete} />)
  fireEvent.keyDown(row("过期"), { key: "Delete" })
  pump(24)
  expect(onDelete).toHaveBeenCalledWith("stale")
  expect(screen.queryByRole("button", { name: "过期" })).toBeNull()
})

test("触屏向下拖也可以扔", () => {
  const onDelete = vi.fn()
  render(<TossToTrash onDelete={onDelete} />)
  const item = row("旧稿")
  fireEvent.pointerDown(item, { button: 0, clientX: 0, clientY: 0, pointerId: 3, pointerType: "touch", timeStamp: 0 })
  fireEvent.pointerUp(item, { button: 0, clientX: 4, clientY: 110, pointerId: 3, pointerType: "touch", timeStamp: 50 })
  pump(24)
  expect(onDelete).toHaveBeenCalledWith("old")
})

test("减弱动效时 Delete 立刻删除，并且不申请动画帧", () => {
  reduceMotion = true
  const onDelete = vi.fn()
  render(<TossToTrash onDelete={onDelete} />)
  expect(document.querySelector("[data-slot='toss-to-trash']")).toHaveAttribute("data-reduced", "true")
  fireEvent.keyDown(row("旧稿"), { key: "Backspace" })
  expect(onDelete).toHaveBeenCalledWith("old")
  expect(queue.size).toBe(0)
})

"use client"

import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent as ReactPointerEvent } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface TrashItem {
  id: string
  label: string
}

export interface TossToTrashProps {
  items?: readonly TrashItem[]
  onDelete?: (id: string) => void
  color?: string
  size?: number
  duration?: number
  arc?: number
  className?: string
}

const DEFAULT_ITEMS: readonly TrashItem[] = [
  { id: "old", label: "旧稿" },
  { id: "dup", label: "重复" },
  { id: "stale", label: "过期" },
]

const DROP_DISTANCE = 64

interface Origin {
  x: number
  y: number
  t: number
}

interface Flight {
  id: string
  x: number
  y: number
  endX: number
  endY: number
  lift: number
}

function TossToTrash({
  items = DEFAULT_ITEMS,
  onDelete,
  color,
  size = 48,
  duration = 520,
  arc = 72,
  className,
}: TossToTrashProps) {
  const reduced = usePrefersReducedMotion()
  const [rows, setRows] = useState<readonly TrashItem[]>(items)
  const [drag, setDrag] = useState<{ id: string; x: number; y: number } | null>(null)
  const [pose, setPose] = useState({ x: 0, y: 0 })
  const [flyId, setFlyId] = useState<string | null>(null)
  const origin = useRef<Origin | null>(null)
  const flight = useRef<Flight | null>(null)
  const trashRef = useRef<HTMLDivElement>(null)
  const done = useRef(new Set<string>())
  const onDeleteRef = useRef(onDelete)
  const reducedRef = useRef(reduced)
  const durationRef = useRef(duration)
  useEffect(() => {
    onDeleteRef.current = onDelete
    reducedRef.current = reduced
    durationRef.current = duration
  })
  const borderColor = color ?? "var(--destructive)"

  function finish(id: string) {
    if (done.current.has(id)) return
    done.current.add(id)
    flight.current = null
    setFlyId(null)
    setDrag(null)
    setRows((prev) => prev.filter((item) => item.id !== id))
    onDeleteRef.current?.(id)
  }

  useEffect(() => {
    const current = flight.current
    if (!current) return
    if (reduced) {
      finish(current.id)
      return
    }
    const startX = current.x
    const startY = current.y
    const endX = current.endX
    const endY = current.endY
    const lift = current.lift
    let last = 0
    let elapsed = 0
    let raf = 0
    const step = (now: number) => {
      if (reducedRef.current) {
        finish(current.id)
        return
      }
      const dt = last === 0 ? 16 : Math.min(32, Math.max(0, now - last))
      last = now
      elapsed += dt
      const span = Math.max(80, durationRef.current)
      const progress = Math.min(1, elapsed / span)
      const x = startX + (endX - startX) * progress
      const y = startY + (endY - startY) * progress - Math.sin(Math.PI * progress) * lift
      if (progress >= 1) {
        finish(current.id)
        return
      }
      setPose({ x, y })
      raf = requestAnimationFrame(step)
    }
    raf = requestAnimationFrame(step)
    return () => cancelAnimationFrame(raf)
  }, [flyId, reduced])

  function landing(from: HTMLElement) {
    const trash = trashRef.current?.getBoundingClientRect()
    const self = from.getBoundingClientRect()
    if (!trash || trash.width <= 0 || trash.height <= 0 || self.width <= 0 || self.height <= 0) return { x: 0, y: 180 }
    return {
      x: trash.left + trash.width / 2 - (self.left + self.width / 2),
      y: trash.top + trash.height / 2 - (self.top + self.height / 2),
    }
  }

  function launch(id: string, x: number, y: number, vy: number, from: HTMLElement) {
    setDrag(null)
    if (reduced) {
      finish(id)
      return
    }
    const end = landing(from)
    flight.current = { id, x, y, endX: end.x, endY: end.y, lift: arc + Math.max(0, -vy) * 12 }
    setPose({ x, y })
    setFlyId(id)
  }

  function overTrash(event: ReactPointerEvent<HTMLButtonElement>) {
    const rect = trashRef.current?.getBoundingClientRect()
    if (!rect || rect.width <= 0 || rect.height <= 0) return false
    return event.clientX >= rect.left && event.clientX <= rect.right && event.clientY >= rect.top && event.clientY <= rect.bottom
  }

  function onPointerDown(event: ReactPointerEvent<HTMLButtonElement>, id: string) {
    if (flyId) return
    if (event.pointerType === "mouse" && event.button !== 0) return
    event.currentTarget.setPointerCapture?.(event.pointerId)
    origin.current = { x: event.clientX, y: event.clientY, t: event.timeStamp }
    setDrag({ id, x: 0, y: 0 })
  }

  function onPointerMove(event: ReactPointerEvent<HTMLButtonElement>) {
    const start = origin.current
    if (!start || !drag) return
    setDrag({ id: drag.id, x: event.clientX - start.x, y: event.clientY - start.y })
  }

  function onPointerUp(event: ReactPointerEvent<HTMLButtonElement>) {
    const start = origin.current
    const current = drag
    origin.current = null
    if (!start || !current) return
    const dx = event.clientX - start.x
    const dy = event.clientY - start.y
    const dt = Math.max(16, event.timeStamp - start.t)
    if (dy < DROP_DISTANCE && !overTrash(event)) {
      setDrag(null)
      return
    }
    launch(current.id, dx, dy, dy / dt, event.currentTarget)
  }

  function onKeyDown(event: KeyboardEvent<HTMLButtonElement>, id: string) {
    if (flyId) return
    if (event.key !== "Delete" && event.key !== "Backspace" && event.key !== "ArrowDown") return
    event.preventDefault()
    launch(id, 0, 0, 1, event.currentTarget)
  }

  return (
    <div className={cn("flex w-full max-w-sm flex-col gap-4", className)} data-reduced={reduced ? "true" : undefined} data-slot="toss-to-trash">
      <ul className="m-0 flex list-none flex-col gap-2 p-0">
        {rows.map((item) => {
          const flying = flyId === item.id
          const dragging = drag?.id === item.id
          const point = flying ? pose : dragging ? drag : null
          return (
            <li key={item.id}>
              <button
                className={cn(
                  "bg-card text-card-foreground w-full touch-none rounded-xl border px-3 text-left select-none",
                  "motion-reduce:transition-none",
                  dragging || flying || reduced ? "transition-none" : "transition-transform duration-200",
                )}
                data-item={item.id}
                onKeyDown={(event) => onKeyDown(event, item.id)}
                onPointerCancel={() => {
                  origin.current = null
                  setDrag(null)
                }}
                onPointerDown={(event) => onPointerDown(event, item.id)}
                onPointerMove={onPointerMove}
                onPointerUp={onPointerUp}
                style={{
                  borderColor,
                  height: size,
                  transform: point ? `translate(${point.x}px, ${point.y}px)` : undefined,
                }}
                type="button"
              >
                {item.label}
              </button>
            </li>
          )
        })}
      </ul>
      <div
        aria-label="垃圾桶"
        className="grid place-items-center rounded-2xl border border-dashed text-sm motion-reduce:transition-none"
        data-slot="toss-trash"
        ref={trashRef}
        style={{ borderColor, color: borderColor, height: size + 16 }}
      >
        垃圾桶
      </div>
    </div>
  )
}

export { TossToTrash }

