// Ported from ns-ui (MIT, (c) 2026 Nikolas Sapalidis) — https://github.com/nikolas-sapa/ns-ui/blob/main/registry/core/undo-ghost-row/component.tsx

import {
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion";
import { useAnimationActive } from "@/hooks/use-animation-active";
import type { RefObject } from "react";

type NsJob = { token: number; cb: (now: number) => void; raf: number };
type NsApi = {
  requestFrame: (cb: (now: number) => void) => number;
  cancelFrame: (id: number | null | undefined) => void;
  motionNow: () => number;
};

const nsApi: NsApi = {
  requestFrame: (cb) => requestAnimationFrame((t) => cb(t)),
  cancelFrame: (id) => {
    if (id) cancelAnimationFrame(id);
  },
  motionNow: () => performance.now(),
};

function nsRequestFrame(cb: (now: number) => void) {
  return nsApi.requestFrame(cb);
}
function nsCancelFrame(id: number | null | undefined) {
  nsApi.cancelFrame(id);
}
function nsMotionNow() {
  return nsApi.motionNow();
}

function useNsBind(rootRef: RefObject<HTMLElement | null>) {
  const reduced = usePrefersReducedMotion();
  const live = useAnimationActive(rootRef as RefObject<Element | null>);
  const liveRef = useRef(live);
  const reducedRef = useRef(reduced);
  const holdRef = useRef(0);
  const offsetRef = useRef(0);
  const jobsRef = useRef(new Map<number, NsJob>());
  const seqRef = useRef(1);

  const motionNow = () => {
    const raw = performance.now();
    if (!liveRef.current) {
      if (holdRef.current === 0) holdRef.current = raw;
      return holdRef.current - offsetRef.current;
    }
    if (holdRef.current !== 0) {
      offsetRef.current += raw - holdRef.current;
      holdRef.current = 0;
    }
    return raw - offsetRef.current;
  };

  const requestFrame = (cb: (now: number) => void) => {
    const token = seqRef.current++;
    const job: NsJob = { token, cb, raf: 0 };
    jobsRef.current.set(token, job);
    const kick = () => {
      if (!liveRef.current) {
        if (holdRef.current === 0) holdRef.current = performance.now();
        job.raf = 0;
        return;
      }
      job.raf = requestAnimationFrame(() => {
        if (!jobsRef.current.has(token)) return;
        if (!liveRef.current) {
          job.raf = 0;
          if (holdRef.current === 0) holdRef.current = performance.now();
          return;
        }
        jobsRef.current.delete(token);
        cb(motionNow());
      });
    };
    kick();
    return token;
  };

  const cancelFrame = (id: number | null | undefined) => {
    if (id == null) return;
    const job = jobsRef.current.get(id);
    if (!job) return;
    if (job.raf) cancelAnimationFrame(job.raf);
    jobsRef.current.delete(id);
  };

  useEffect(() => {
    liveRef.current = live;
    reducedRef.current = reduced;
  }, [live, reduced]);

  useEffect(() => {
    nsApi.requestFrame = requestFrame;
    nsApi.cancelFrame = cancelFrame;
    nsApi.motionNow = motionNow;
  });

  useEffect(() => {
    if (!live) return;
    for (const job of [...jobsRef.current.values()]) {
      if (job.raf) continue;
      const { token, cb } = job;
      job.raf = requestAnimationFrame(() => {
        if (!jobsRef.current.has(token)) return;
        if (!liveRef.current) {
          job.raf = 0;
          return;
        }
        jobsRef.current.delete(token);
        cb(motionNow());
      });
    }
  }, [live]);

  useEffect(
    () => () => {
      for (const job of jobsRef.current.values()) {
        if (job.raf) cancelAnimationFrame(job.raf);
      }
      jobsRef.current.clear();
    },
    [],
  );

  return { reduced, live, motionOn: live && !reduced, requestFrame, cancelFrame, motionNow };
}

function NsPause({ slot }: { slot: string }) {
  return (
    <style>{`[data-slot="${slot}"][data-motion="off"],[data-slot="${slot}"][data-motion="off"] *{animation-play-state:paused !important}`}</style>
  );
}

// ---------------------------------------------------------------------------
// AfterImageList — inline undo for destructive list actions, no toast. On
// delete, a row swaps in place for a same-height ghost: 1px dashed --border,
// the item title at 40% opacity, a real "Undo delete: <title>" button. The
// ghost's height is driven directly by the Web Animations API (linear,
// ~8s, full height -> 0) so remaining time reads as remaining height —
// siblings below ride the shrink smoothly since it's plain document flow.
// Hover or focus pauses the Animation object in place; a click cancels it,
// reads the live height, and starts a second animation back up to full
// height with an ease-out-expo curve, restoring the row on finish. Deletion
// announces the undo window through an aria-live region; the timer is
// genuinely paused while the ghost has keyboard focus, so assistive tech is
// never raced by the clock. prefers-reduced-motion holds the ghost at full
// height indefinitely (no auto-collapse) and adds an explicit dismiss
// button, since there is no longer a timeout to rely on.
// ---------------------------------------------------------------------------

export interface AfterImageItem {
  id: string;
  title: string;
  subtitle?: string;
}

export interface AfterImageListProps {
  /** the deletable rows */
  items: AfterImageItem[];
  /** ms the ghost takes to collapse to zero height and finalize the delete */
  ghostMs?: number;
  /** called immediately when a row's delete is triggered, before the ghost window */
  onDelete?: (item: AfterImageItem) => void;
  /** called if the delete is undone within the ghost window */
  onRestore?: (item: AfterImageItem) => void;
  /** fires once the ghost window elapses (or is dismissed) and the item is gone for good */
  onExpire?: (item: AfterImageItem) => void;
  /** extra classes merged onto the rendered root element */
  className?: string;
}

// Re-inflate curve: an ease-out-expo approximation, matching the house
// spring-adjacent easing used elsewhere in this registry (see approval-inline-diff's
// collapse transition) rather than inventing a new one.
const REINFLATE_EASE = "cubic-bezier(0.16, 1, 0.3, 1)";
const REINFLATE_MS = 380;

function useReducedMotion() {
  return usePrefersReducedMotion();
}

function TrashIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3.5 w-3.5" fill="none" aria-hidden>
      <path
        d="M3 4.5h10M6.5 4.5V3a1 1 0 0 1 1-1h1a1 1 0 0 1 1 1v1.5M4.5 4.5l.6 8.2a1 1 0 0 0 1 .8h3.8a1 1 0 0 0 1-.8l.6-8.2"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function UndoIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3.5 w-3.5 shrink-0" fill="none" aria-hidden>
      <path
        d="M4 6.5H10.5a3 3 0 0 1 0 6H8"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
      <path
        d="M6.2 4 4 6.5l2.2 2.5"
        stroke="currentColor"
        strokeWidth="1.4"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function XIcon() {
  return (
    <svg viewBox="0 0 16 16" className="h-3.5 w-3.5" fill="none" aria-hidden>
      <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" />
    </svg>
  );
}

function Row({ item, onDelete }: { item: AfterImageItem; onDelete: () => void }) {
  return (
    <li className="border-b border-border last:border-b-0">
      <div className="flex items-center gap-3 px-4 py-3">
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm text-foreground">{item.title}</p>
          {item.subtitle ? (
            <p className="truncate text-xs text-muted-foreground">{item.subtitle}</p>
          ) : null}
        </div>
        <button
          type="button"
          data-afterimage-delete
          onClick={onDelete}
          aria-label={`Delete ${item.title}`}
          className="shrink-0 rounded-sm p-1.5 text-muted-foreground transition-colors hover:bg-background hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
        >
          <TrashIcon />
        </button>
      </div>
    </li>
  );
}

function GhostRow({
  item,
  ghostMs,
  reduced,
  active,
  onRestore,
  onExpire,
}: {
  item: AfterImageItem;
  ghostMs: number;
  reduced: boolean;
  active: boolean;
  onRestore: () => void;
  onExpire: () => void;
}) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const animRef = useRef<Animation | null>(null);
  const fullRef = useRef(0);
  const hoverRef = useRef(false);
  const focusRef = useRef(false);
  const settledRef = useRef(false); // true once restored or expired — guards double-fire

  useLayoutEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const full = el.scrollHeight;
    fullRef.current = full;
    el.style.height = `${full}px`;

    if (reduced) return; // static: no clock to race, dismiss button finalizes instead

    const anim = el.animate(
      [{ height: `${full}px` }, { height: "0px" }],
      { duration: ghostMs, easing: "linear", fill: "forwards" }
    );
    animRef.current = anim;
    anim.onfinish = () => {
      if (settledRef.current) return;
      settledRef.current = true;
      onExpire();
    };
    return () => {
      anim.cancel();
    };
    // ghostMs/onExpire intentionally fixed for this ghost's lifetime — a
    // prop change mid-collapse shouldn't restart the clock out from under it
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [reduced]);

  useEffect(() => {
    const anim = animRef.current;
    if (!anim || reduced) return;
    if (!active || hoverRef.current || focusRef.current) anim.pause();
    else if (anim.playState === "paused") anim.play();
  }, [active, reduced]);

  function pause() {
    animRef.current?.pause();
  }

  function maybeResume() {
    if (hoverRef.current || focusRef.current) return;
    const anim = animRef.current;
    if (anim && anim.playState === "paused") anim.play();
  }

  function handleRestore() {
    if (settledRef.current) return;
    settledRef.current = true;
    const el = wrapRef.current;
    const anim = animRef.current;
    if (!el || reduced || !anim) {
      onRestore();
      return;
    }
    const currentHeight = el.getBoundingClientRect().height;
    anim.cancel();
    const reinflate = el.animate(
      [{ height: `${currentHeight}px` }, { height: `${fullRef.current}px` }],
      { duration: REINFLATE_MS, easing: REINFLATE_EASE, fill: "forwards" }
    );
    animRef.current = reinflate;
    reinflate.onfinish = () => onRestore();
  }

  return (
    <li className="border-b border-border last:border-b-0">
      <div ref={wrapRef} className="overflow-hidden">
        <div
          className="flex items-center gap-2 border border-dashed border-border px-4 py-3"
          onPointerEnter={() => {
            hoverRef.current = true;
            pause();
          }}
          onPointerLeave={() => {
            hoverRef.current = false;
            maybeResume();
          }}
          onFocus={() => {
            focusRef.current = true;
            pause();
          }}
          onBlur={() => {
            focusRef.current = false;
            maybeResume();
          }}
        >
          <button
            type="button"
            data-afterimage-undo
            onClick={handleRestore}
            aria-label={`Undo delete: ${item.title}`}
            className="flex min-w-0 flex-1 items-center gap-2 text-left focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
          >
            <UndoIcon />
            <span className="truncate text-sm text-foreground/40">{item.title}</span>
          </button>
          {reduced ? (
            <button
              type="button"
              onClick={() => {
                if (settledRef.current) return;
                settledRef.current = true;
                onExpire();
              }}
              aria-label={`Dismiss: finish deleting ${item.title}`}
              className="shrink-0 rounded-sm p-1.5 text-muted-foreground transition-colors hover:bg-background hover:text-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring"
            >
              <XIcon />
            </button>
          ) : (
            <span className="shrink-0 font-mono text-[10px] uppercase tracking-wide text-muted-foreground">
              Undo
            </span>
          )}
        </div>
      </div>
    </li>
  );
}

export function AfterImageList({
  items,
  ghostMs = 8000,
  onDelete,
  onRestore,
  onExpire,
  className = "",
}: AfterImageListProps) {
  const nsRootRef = useRef<HTMLDivElement | null>(null);
  const nsMotion = useNsBind(nsRootRef as RefObject<HTMLElement | null>);
  const nsRequestFrame = nsMotion.requestFrame;
  const nsCancelFrame = nsMotion.cancelFrame;
  const nsMotionNow = nsMotion.motionNow;

  const [rows, setRows] = useState(() => items.map((it) => ({ ...it, ghosted: false })));
  const [announcement, setAnnouncement] = useState("");
  const reduced = useReducedMotion();
  const rowsRef = useRef(rows);
  useEffect(() => {
    rowsRef.current = rows;
  }, [rows]);

  function handleDelete(id: string) {
    const item = rowsRef.current.find((r) => r.id === id);
    if (!item) return;
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, ghosted: true } : r)));
    onDelete?.(item);
    setAnnouncement(
      reduced
        ? `Deleted ${item.title}. Undo available until dismissed.`
        : `Deleted ${item.title}. Undo available for ${Math.round(ghostMs / 1000)} seconds.`
    );
  }

  function handleRestore(id: string) {
    const item = rowsRef.current.find((r) => r.id === id);
    setRows((rs) => rs.map((r) => (r.id === id ? { ...r, ghosted: false } : r)));
    if (item) {
      onRestore?.(item);
      setAnnouncement(`Restored ${item.title}.`);
    }
  }

  function handleExpire(id: string) {
    const item = rowsRef.current.find((r) => r.id === id);
    setRows((rs) => rs.filter((r) => r.id !== id));
    if (item) onExpire?.(item);
  }

  return (
    <div ref={nsRootRef} data-slot="undo-ghost-row" data-reduced={nsMotion.reduced ? "true" : "false"} data-motion={nsMotion.motionOn ? "on" : "off"} className={className}>
      <NsPause slot="undo-ghost-row" />
      {rows.length === 0 ? (
        <p className="rounded-md border border-dashed border-border px-4 py-6 text-center text-sm text-muted-foreground">
          Nothing here.
        </p>
      ) : (
        <ul className="overflow-hidden rounded-md border border-border bg-card">
          {rows.map((r) =>
            r.ghosted ? (
              <GhostRow
                key={r.id}
                item={r}
                ghostMs={ghostMs}
                reduced={reduced}
                active={nsMotion.live}
                onRestore={() => handleRestore(r.id)}
                onExpire={() => handleExpire(r.id)}
              />
            ) : (
              <Row key={r.id} item={r} onDelete={() => handleDelete(r.id)} />
            )
          )}
        </ul>
      )}
      <p role="status" aria-live="polite" className="sr-only">
        {announcement}
      </p>
    </div>
  );
}

"use client"

// Ported from SmoothUI (MIT) — https://github.com/educlopez/smoothui/blob/main/packages/smoothui/components/unlock-face-id/index.tsx


import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"
import { AnimatePresence, motion } from "motion/react";
import type { ReactNode } from "react";
import { useCallback, useEffect, useId, useRef, useState } from "react";

export type UnlockStatus = "idle" | "scanning" | "success" | "error";

export type UnlockFaceIdProps = {
  /** Content gated behind the scan — blurred while locked, sharp once unlocked */
  children?: ReactNode;
  /** Additional CSS classes */
  className?: string;
  /** Message shown when the status is `error` */
  errorMessage?: string;
  /** Accessible label for the scan trigger */
  label?: string;
  /** Fired when an uncontrolled scan resolves successfully */
  onComplete?: () => void;
  /** Fired whenever the trigger is activated */
  onScan?: () => void;
  /** How long an uncontrolled scan takes, in ms */
  scanDuration?: number;
  /** Rendered size of the glyph, in px */
  size?: number;
  /** Controlled status — omit for uncontrolled behaviour */
  status?: UnlockStatus;
};

const DEFAULT_SIZE = 128;
const DEFAULT_SCAN_DURATION = 1800;
const DEFAULT_ERROR_MESSAGE = "Face not recognized. Try again.";

/* -------------------------------------------------------------------------- */
/* Motion tokens                                                              */
/* -------------------------------------------------------------------------- */

const EASE_OUT: [number, number, number, number] = [0.23, 1, 0.32, 1];
const EASE_IN_OUT: [number, number, number, number] = [0.645, 0.045, 0.355, 1];
const INSTANT = { duration: 0 };
const CHECK_SPRING = { bounce: 0.28, duration: 0.4, type: "spring" as const };
const GLYPH_SPRING = { bounce: 0.1, duration: 0.25, type: "spring" as const };
const BRACKET_DRAW = 0.4;
const BRACKET_STAGGER = 0.07;
const FACE_DELAY = 0.26;
const FACE_DRAW = 0.42;
const FACE_STAGGER = 0.07;
const SCAN_SWEEP = 1.5;
const SHAKE_DURATION = 0.4;
const CONTENT_REVEAL = 0.4;
const SHAKE_KEYFRAMES = [0, -7, 7, -5, 5, -2, 0];

/* -------------------------------------------------------------------------- */
/* Geometry — Apple's Face ID mark: four corner brackets + a schematic face    */
/* -------------------------------------------------------------------------- */

const VIEWBOX = 100;
const STROKE_WIDTH = 4;
const CHECK_STROKE_WIDTH = 5;

/** Four corner brackets only — no full outline — with a clear gap between them. */
const BRACKET_PATHS = [
  "M8 34 L8 28 A20 20 0 0 1 28 8 L34 8",
  "M66 8 L72 8 A20 20 0 0 1 92 28 L92 34",
  "M92 66 L92 72 A20 20 0 0 1 72 92 L66 92",
  "M34 92 L28 92 A20 20 0 0 1 8 72 L8 66",
];

/** Two short vertical eye strokes, a nose that turns right at the bottom, and a
 *  shallow smile with small upward ticks at each end. */
const FACE_PATHS = [
  "M36 38 L36 47",
  "M64 38 L64 47",
  "M50 38 L50 54 Q50 57.5 53.5 57.5 L56 57.5",
  "M36 61 L36 66 Q50 73 64 66 L64 61",
];

const CHECK_PATH = "M30 52 L44 66 L72 34";

const SCAN_CLIP = { height: 84, rx: 22, width: 84, x: 8, y: 8 };
const SCAN_BAND_HEIGHT = 18;
const SCAN_TRAVEL = 34;

const STATUS_MESSAGES: Record<Exclude<UnlockStatus, "error">, string> = {
  idle: "Ready to scan.",
  scanning: "Scanning face…",
  success: "Identity confirmed. Unlocked.",
};

const STROKE_BY_STATUS: Record<UnlockStatus, string> = {
  error: "var(--color-destructive, #ef4444)",
  idle: "currentColor",
  scanning: "currentColor",
  success: "var(--color-green, #22c55e)",
};

/* -------------------------------------------------------------------------- */
/* Glyph                                                                      */
/* -------------------------------------------------------------------------- */

type FaceGlyphProps = {
  canAnimate: boolean;
  clipId: string;
  gradientId: string;
  isScanning: boolean;
  stroke: string;
};

const FaceGlyph = ({
  canAnimate,
  clipId,
  gradientId,
  isScanning,
  stroke,
}: FaceGlyphProps) => (
  <motion.g
    animate={{ opacity: 1, scale: 1 }}
    exit={
      canAnimate
        ? { opacity: 0, scale: 0.82 }
        : { opacity: 0, transition: INSTANT }
    }
    initial={
      canAnimate ? { opacity: 0, scale: 0.94 } : { opacity: 1, scale: 1 }
    }
    style={{ transformOrigin: "50px 50px" }}
    transition={canAnimate ? GLYPH_SPRING : INSTANT}
  >
    {BRACKET_PATHS.map((path, index) => (
      <motion.path
        animate={{ pathLength: 1 }}
        d={path}
        fill="none"
        initial={canAnimate ? { pathLength: 0 } : { pathLength: 1 }}
        key={path}
        stroke={stroke}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={STROKE_WIDTH}
        transition={
          canAnimate
            ? {
                delay: index * BRACKET_STAGGER,
                duration: BRACKET_DRAW,
                ease: EASE_OUT,
              }
            : INSTANT
        }
      />
    ))}

    {FACE_PATHS.map((path, index) => (
      <motion.path
        animate={{ pathLength: 1 }}
        d={path}
        fill="none"
        initial={canAnimate ? { pathLength: 0 } : { pathLength: 1 }}
        key={path}
        stroke={stroke}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeWidth={STROKE_WIDTH}
        transition={
          canAnimate
            ? {
                delay: FACE_DELAY + index * FACE_STAGGER,
                duration: FACE_DRAW,
                ease: EASE_OUT,
              }
            : INSTANT
        }
      />
    ))}

    {isScanning && canAnimate ? (
      <g clipPath={`url(#${clipId})`}>
        <motion.g
          animate={{ y: SCAN_TRAVEL }}
          initial={{ y: -SCAN_TRAVEL }}
          transition={{
            duration: SCAN_SWEEP,
            ease: EASE_IN_OUT,
            repeat: Number.POSITIVE_INFINITY,
            repeatType: "reverse",
          }}
        >
          <rect
            fill={`url(#${gradientId})`}
            height={SCAN_BAND_HEIGHT}
            width={SCAN_CLIP.width}
            x={SCAN_CLIP.x}
            y={50 - SCAN_BAND_HEIGHT / 2}
          />
          <line
            opacity={0.9}
            stroke="var(--color-brand, #6366f1)"
            strokeLinecap="round"
            strokeWidth={1.5}
            x1={SCAN_CLIP.x + 2}
            x2={SCAN_CLIP.x + SCAN_CLIP.width - 2}
            y1={50 + SCAN_BAND_HEIGHT / 2}
            y2={50 + SCAN_BAND_HEIGHT / 2}
          />
        </motion.g>
      </g>
    ) : null}
  </motion.g>
);

type CheckGlyphProps = {
  canAnimate: boolean;
};

const CheckGlyph = ({ canAnimate }: CheckGlyphProps) => (
  <motion.g
    animate={{ opacity: 1, scale: 1 }}
    initial={canAnimate ? { opacity: 0, scale: 0.6 } : { opacity: 1, scale: 1 }}
    style={{ transformOrigin: "50px 50px" }}
    transition={canAnimate ? CHECK_SPRING : INSTANT}
  >
    <motion.path
      animate={{ pathLength: 1 }}
      d={CHECK_PATH}
      fill="none"
      initial={canAnimate ? { pathLength: 0 } : { pathLength: 1 }}
      stroke="var(--color-green, #22c55e)"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={CHECK_STROKE_WIDTH}
      transition={canAnimate ? CHECK_SPRING : INSTANT}
    />
  </motion.g>
);

/* -------------------------------------------------------------------------- */
/* Root                                                                      */
/* -------------------------------------------------------------------------- */

const UnlockFaceId = ({
  children,
  className,
  errorMessage = DEFAULT_ERROR_MESSAGE,
  label = "Scan to unlock",
  onComplete,
  onScan,
  scanDuration = DEFAULT_SCAN_DURATION,
  size = DEFAULT_SIZE,
  status: controlledStatus,
}: UnlockFaceIdProps) => {
  const shouldReduceMotion = Boolean(usePrefersReducedMotion());
  const hostRef = useRef<HTMLDivElement>(null);
  const motionOn = useAnimationActive(hostRef);
  const motionOnRef = useRef(motionOn);
  const deadlineRef = useRef<number | null>(null);
  const canAnimate = !shouldReduceMotion && motionOn;
  const isControlled = controlledStatus !== undefined;
  const [internalStatus, setInternalStatus] = useState<UnlockStatus>("idle");
  const status = isControlled ? controlledStatus : internalStatus;
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const reactId = useId();
  const uid = reactId.replace(/:/g, "");
  const statusMessageId = `unlock-face-id-status-${uid}`;
  const clipId = `unlock-face-id-clip-${uid}`;
  const gradientId = `unlock-face-id-gradient-${uid}`;

  useEffect(
    () => () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    },
    []
  );

  const armTimer = useCallback(() => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
      timeoutRef.current = null;
    }
    const deadline = deadlineRef.current;
    if (deadline == null || !motionOnRef.current) {
      return;
    }
    timeoutRef.current = setTimeout(() => {
      timeoutRef.current = null;
      deadlineRef.current = null;
      setInternalStatus("success");
      onComplete?.();
    }, Math.max(0, deadline - performance.now()));
  }, [onComplete]);

  useEffect(() => {
    motionOnRef.current = motionOn;
    if (deadlineRef.current != null) {
      armTimer();
    }
  }, [armTimer, motionOn]);

  const beginScan = useCallback(() => {
    onScan?.();
    if (isControlled) {
      return;
    }
    setInternalStatus("scanning");
    deadlineRef.current = performance.now() + scanDuration;
    armTimer();
  }, [armTimer, isControlled, onScan, scanDuration]);

  const handleTriggerClick = useCallback(() => {
    if (status === "error") {
      onScan?.();
      if (!isControlled) {
        setInternalStatus("idle");
      }
      return;
    }
    if (status === "idle") {
      beginScan();
    }
  }, [beginScan, isControlled, onScan, status]);

  const isBusy = status === "scanning";
  const isUnlocked = status === "success";
  const statusMessage =
    status === "error" ? errorMessage : STATUS_MESSAGES[status];

  return (
    <div
      className={cn("flex w-full flex-col items-center gap-4", className)}
      data-reduced={shouldReduceMotion ? "true" : "false"}
      data-slot="unlock-face-id"
      ref={hostRef}
    >
      <button
        aria-busy={isBusy}
        aria-describedby={statusMessageId}
        aria-label={label}
        className="relative flex shrink-0 cursor-pointer items-center justify-center rounded-3xl text-foreground outline-none transition-transform duration-150 ease-out focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-background active:scale-95 disabled:cursor-default disabled:active:scale-100 motion-reduce:transition-none motion-reduce:active:scale-100"
        disabled={isBusy || isUnlocked}
        onClick={handleTriggerClick}
        style={{ height: size, width: size }}
        type="button"
      >
        <motion.svg
          animate={{
            x: status === "error" && canAnimate ? SHAKE_KEYFRAMES : 0,
          }}
          aria-hidden="true"
          className="h-full w-full overflow-visible"
          transition={
            canAnimate
              ? { duration: SHAKE_DURATION, ease: EASE_IN_OUT }
              : INSTANT
          }
          viewBox={`0 0 ${VIEWBOX} ${VIEWBOX}`}
        >
          <defs>
            <clipPath id={clipId}>
              <rect
                height={SCAN_CLIP.height}
                rx={SCAN_CLIP.rx}
                width={SCAN_CLIP.width}
                x={SCAN_CLIP.x}
                y={SCAN_CLIP.y}
              />
            </clipPath>
            <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
              <stop
                offset="0%"
                stopColor="var(--color-brand, #6366f1)"
                stopOpacity={0}
              />
              <stop
                offset="100%"
                stopColor="var(--color-brand, #6366f1)"
                stopOpacity={0.45}
              />
            </linearGradient>
          </defs>

          <AnimatePresence mode="wait">
            {isUnlocked ? (
              <CheckGlyph canAnimate={canAnimate} key="check" />
            ) : (
              <FaceGlyph
                canAnimate={canAnimate}
                clipId={clipId}
                gradientId={gradientId}
                isScanning={isBusy}
                key="face"
                stroke={STROKE_BY_STATUS[status]}
              />
            )}
          </AnimatePresence>
        </motion.svg>
      </button>

      <p
        aria-live="polite"
        className={cn(
          "text-center font-medium text-sm transition-colors duration-200",
          status === "error" && "text-destructive",
          status === "success" && "text-green",
          (status === "idle" || status === "scanning") &&
            "text-muted-foreground"
        )}
        id={statusMessageId}
        role="status"
      >
        {statusMessage}
      </p>

      {children ? (
        <motion.div
          animate={{
            filter: isUnlocked ? "blur(0px)" : "blur(9px)",
            opacity: isUnlocked ? 1 : 0.5,
          }}
          className={cn("w-full", isUnlocked ? "" : "pointer-events-none")}
          initial={false}
          transition={
            canAnimate ? { duration: CONTENT_REVEAL, ease: EASE_OUT } : INSTANT
          }
        >
          {children}
        </motion.div>
      ) : null}
    </div>
  );
};

