test("指针开始上传后文件离开待命位置，完成后再排成一行并回调", () => {
  const onComplete = vi.fn()
  render(<UploadOrbit onComplete={onComplete} />)
  const before = document.querySelector("[data-file='brief']")?.getAttribute("style")
  fireEvent.pointerUp(action("开始上传"), { button: 0, pointerId: 1, pointerType: "mouse" })
  expect(document.querySelector("[data-slot='upload-orbit']")).toHaveAttribute("data-layout", "orbit")
  expect(onComplete).not.toHaveBeenCalled()
  pump(3)
  expect(document.querySelector("[data-file='brief']")?.getAttribute("style")).not.toEqual(before)
  fireEvent.pointerUp(action("完成上传"), { button: 0, pointerId: 1, pointerType: "mouse" })
  expect(document.querySelector("[data-slot='upload-orbit']")).toHaveAttribute("data-layout", "settle")
  pump(60)
  expect(onComplete).toHaveBeenCalledTimes(1)
  expect(document.querySelector("[data-slot='upload-orbit']")).toHaveAttribute("data-layout", "row")
  expect(screen.getByText("文件已排成一行")).toBeInTheDocument()
  expect(queue.size).toBe(0)
})

test("回车可以开始并完成上传", () => {
  const onComplete = vi.fn()
  render(<UploadOrbit onComplete={onComplete} />)
  fireEvent.keyDown(action("开始上传"), { key: "Enter" })
  expect(document.querySelector("[data-slot='upload-orbit']")).toHaveAttribute("data-layout", "orbit")
  fireEvent.keyDown(action("完成上传"), { key: " " })
  pump(60)
  expect(onComplete).toHaveBeenCalledTimes(1)
  expect(action("已完成")).toBeDisabled()
})

test("触屏点按同样可以开始并完成，不依赖悬停", () => {
  const onComplete = vi.fn()
  render(<UploadOrbit onComplete={onComplete} />)
  fireEvent.pointerUp(action("开始上传"), { button: 0, pointerId: 2, pointerType: "touch" })
  expect(document.querySelector("[data-slot='upload-orbit']")).toHaveAttribute("data-layout", "orbit")
  fireEvent.pointerUp(action("完成上传"), { button: 0, pointerId: 2, pointerType: "touch" })
  pump(60)
  expect(onComplete).toHaveBeenCalledTimes(1)
})

test("减弱动效时文件直接排成一行，完成不申请动画帧", () => {
  reduceMotion = true
  const onComplete = vi.fn()
  render(<UploadOrbit onComplete={onComplete} />)
  const root = document.querySelector("[data-slot='upload-orbit']")
  expect(root).toHaveAttribute("data-reduced", "true")
  expect(root).toHaveAttribute("data-layout", "row")
  expect(screen.getByText("文件已排成一行")).toBeInTheDocument()
  fireEvent.keyDown(action("完成上传"), { key: "Enter" })
  fireEvent.pointerUp(action("已完成"), { button: 0, pointerId: 3, pointerType: "touch" })
  expect(onComplete).toHaveBeenCalledTimes(1)
  expect(frameRequests).toBe(0)
  expect(queue.size).toBe(0)
})

"use client"

import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent as ReactPointerEvent } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export interface UploadFile {
  id: string
  name: string
}

export interface UploadOrbitProps {
  files?: readonly UploadFile[]
  onComplete?: () => void
  color?: string
  size?: number
  duration?: number
  className?: string
}

const DEFAULT_FILES: readonly UploadFile[] = [
  { id: "brief", name: "需求.pdf" },
  { id: "sketch", name: "草图.png" },
  { id: "notes", name: "备注.txt" },
]

type Phase = "ready" | "orbit" | "settle" | "row"

interface Point {
  x: number
  y: number
}

function ringPoint(index: number, count: number, spin: number, radius: number): Point {
  const turn = spin + (Math.PI * 2 * index) / Math.max(1, count)
  return { x: Math.cos(turn) * radius, y: Math.sin(turn) * radius * 0.62 }
}

function rowPoint(index: number, count: number, width: number): Point {
  const span = width * 0.7
  const step = count <= 1 ? 0 : span / (count - 1)
  return { x: -span / 2 + step * index, y: width * 0.1 }
}

function readyPoint(index: number, count: number): Point {
  const mid = (count - 1) / 2
  return { x: (index - mid) * 18, y: 4 }
}

function UploadOrbit({
  files = DEFAULT_FILES,
  onComplete,
  color,
  size = 320,
  duration = 1600,
  className,
}: UploadOrbitProps) {
  const reduced = usePrefersReducedMotion()
  const [phase, setPhase] = useState<Phase>("ready")
  const [spin, setSpin] = useState(0)
  const [blend, setBlend] = useState(0)
  const [from, setFrom] = useState<readonly Point[]>([])
  const [acknowledged, setAcknowledged] = useState(false)
  const reported = useRef(false)
  const phaseRef = useRef<Phase>("ready")
  const onCompleteRef = useRef(onComplete)
  const reducedRef = useRef(reduced)
  const durationRef = useRef(duration)
  useEffect(() => {
    phaseRef.current = phase
    onCompleteRef.current = onComplete
    reducedRef.current = reduced
    durationRef.current = duration
  })

  const accent = color ?? "var(--primary)"
  const list = files
  const count = list.length
  const radius = size * 0.28
  const layout: Phase = reduced || phase === "row" ? "row" : phase

  function report() {
    if (reported.current) return
    reported.current = true
    setAcknowledged(true)
    setPhase("row")
    onCompleteRef.current?.()
  }

  useEffect(() => {
    if (reduced || phase !== "orbit") return
    let raf = 0
    let last = 0
    const step = (now: number) => {
      if (reducedRef.current || phaseRef.current !== "orbit") return
      const dt = last === 0 ? 16 : Math.min(32, Math.max(0, now - last))
      last = now
      setSpin((value) => value + (dt / Math.max(1, durationRef.current)) * Math.PI * 2)
      raf = requestAnimationFrame(step)
    }
    raf = requestAnimationFrame(step)
    return () => cancelAnimationFrame(raf)
  }, [phase, reduced])

  useEffect(() => {
    if (reduced || phase !== "settle") return
    let raf = 0
    let last = 0
    let elapsed = 0
    const step = (now: number) => {
      if (reducedRef.current || phaseRef.current !== "settle") {
        if (phaseRef.current === "settle") report()
        return
      }
      const dt = last === 0 ? 16 : Math.min(32, Math.max(0, now - last))
      last = now
      elapsed += dt
      const t = Math.min(1, elapsed / Math.max(1, durationRef.current))
      if (t >= 1) {
        report()
        return
      }
      setBlend(t)
      raf = requestAnimationFrame(step)
    }
    raf = requestAnimationFrame(step)
    return () => cancelAnimationFrame(raf)
  }, [phase, reduced])

  function activate() {
    if (acknowledged) return
    if (reduced || phase === "row" || count === 0) {
      report()
      return
    }
    if (phase === "settle") return
    if (phase === "ready") {
      setSpin(0)
      setPhase("orbit")
      return
    }
    setFrom(list.map((_, index) => ringPoint(index, count, spin, radius)))
    setBlend(0)
    setPhase("settle")
  }

  function onKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.repeat) return
    if (event.key !== "Enter" && event.key !== " ") return
    event.preventDefault()
    activate()
  }

  function onPointerUp(event: ReactPointerEvent<HTMLButtonElement>) {
    if (event.pointerType === "mouse" && event.button !== 0) return
    activate()
  }

  function poseAt(index: number): Point {
    const row = rowPoint(index, count, size)
    if (layout === "row") return row
    if (phase === "ready") return readyPoint(index, count)
    if (phase === "settle") {
      const start = from[index] ?? ringPoint(index, count, spin, radius)
      return { x: start.x + (row.x - start.x) * blend, y: start.y + (row.y - start.y) * blend }
    }
    return ringPoint(index, count, spin, radius)
  }

  const status =
    layout === "row" ? "文件已排成一行" : phase === "orbit" ? "文件正在绕圈上传" : phase === "settle" ? "正在排成一行" : "准备上传"
  const action = acknowledged ? "已完成" : layout === "row" || phase === "orbit" ? "完成上传" : phase === "settle" ? "正在归位" : "开始上传"

  return (
    <div
      className={cn("flex flex-col items-center gap-3", className)}
      data-layout={layout}
      data-reduced={reduced ? "true" : undefined}
      data-slot="upload-orbit"
      style={{ width: size }}
    >
      <div className="relative w-full" style={{ height: Math.round(size * 0.72) }}>
        {count === 0 ? <p className="text-muted-foreground absolute inset-0 grid place-items-center text-sm">没有文件</p> : null}
        {list.map((file, index) => {
          const pose = poseAt(index)
          return (
            <div
              className="bg-card text-card-foreground absolute top-[46%] left-1/2 grid w-24 place-items-center rounded-xl border px-2 py-2 text-sm shadow-sm motion-reduce:transition-none"
              data-file={file.id}
              key={file.id}
              style={{
                borderColor: accent,
                transform: `translate(calc(-50% + ${pose.x}px), calc(-50% + ${pose.y}px))`,
              }}
            >
              {file.name}
            </div>
          )
        })}
      </div>
      <p className="text-muted-foreground text-sm">{status}</p>
      <button
        className="bg-primary text-primary-foreground rounded-full px-4 py-2 text-sm font-medium disabled:opacity-60 motion-reduce:transition-none"
        disabled={acknowledged || (!reduced && phase === "settle")}
        onKeyDown={onKeyDown}
        onPointerUp={onPointerUp}
        type="button"
      >
        {action}
      </button>
    </div>
  )
}

export { UploadOrbit }

"use client"

import * as React from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

export type UptimeStatus = "ok" | "degraded" | "partial" | "major" | "maintenance"

export interface UptimeDay {
  date: string
  status: UptimeStatus
  detail: string
}

export interface UptimeService {
  id: string
  name: string
  days: UptimeDay[]
}

export interface UptimeBarsProps {
  services?: UptimeService[]
  className?: string
}

const TONE: Record<UptimeStatus, string> = {
  ok: "bg-emerald-500",
  degraded: "bg-amber-400",
  partial: "bg-orange-500",
  major: "bg-rose-500",
  maintenance: "bg-sky-400",
}

const LABEL: Record<UptimeStatus, string> = {
  ok: "正常",
  degraded: "降级",
  partial: "部分故障",
  major: "重大故障",
  maintenance: "维护",
}

export function buildUptimeDays(seed: number, length = 90): UptimeDay[] {
  const end = Date.UTC(2026, 9, 21)
  return Array.from({ length }, (_, index) => {
    const date = new Date(end - (length - 1 - index) * 86400000)
    const month = String(date.getUTCMonth() + 1).padStart(2, "0")
    const day = String(date.getUTCDate()).padStart(2, "0")
    const roll = (seed * 17 + index * 13) % 100
    const status: UptimeStatus = roll > 98 ? "major" : roll > 96 ? "partial" : roll > 93 ? "degraded" : roll > 91 ? "maintenance" : "ok"
    return { date: `${date.getUTCFullYear()}-${month}-${day}`, status, detail: LABEL[status] }
  })
}

function uptimePercent(days: UptimeDay[]) {
  const healthy = days.filter((day) => day.status === "ok" || day.status === "maintenance").length
  return (healthy / Math.max(days.length, 1)) * 100
}

const DEFAULTS: UptimeService[] = [
  { id: "api", name: "接口", days: buildUptimeDays(2) },
  { id: "web", name: "站点", days: buildUptimeDays(5) },
]

function UptimeBars({ services = DEFAULTS, className }: UptimeBarsProps) {
  usePrefersReducedMotion()
  const [closed, setClosed] = React.useState<Set<string>>(() => new Set())
  const [tip, setTip] = React.useState<{ service: string; day: UptimeDay } | null>(null)

  return (
    <div data-slot="uptime-bars" className={cn("w-full space-y-4", className)}>
      {services.map((service) => {
        const open = !closed.has(service.id)
        const percent = uptimePercent(service.days)
        return (
          <section key={service.id} className="rounded-xl border p-3">
            <div className="mb-2 flex items-center justify-between gap-3">
              <button
                type="button"
                aria-expanded={open}
                className="text-sm font-medium"
                onClick={() => {
                  setClosed((current) => {
                    const next = new Set(current)
                    if (next.has(service.id)) next.delete(service.id)
                    else next.add(service.id)
                    return next
                  })
                }}
              >
                {service.name}
              </button>
              <span className="text-sm tabular-nums">{percent.toFixed(2)}%</span>
            </div>
            {open ? (
              <div className="flex h-8 w-full items-end gap-px" onMouseLeave={() => setTip((current) => (current?.service === service.id ? null : current))}>
                {service.days.map((day) => (
                  <button
                    key={day.date}
                    type="button"
                    aria-label={`${service.name} ${day.date} ${day.detail}`}
                    className={cn("h-7 min-w-px flex-1 rounded-[1px]", TONE[day.status])}
                    onMouseEnter={() => setTip({ service: service.id, day })}
                    onFocus={() => setTip({ service: service.id, day })}
                  />
                ))}
              </div>
            ) : null}
          </section>
        )
      })}
      {tip ? <p role="tooltip" className="text-sm text-muted-foreground">{tip.day.date} · {tip.day.detail}</p> : null}
    </div>
  )
}

export { UptimeBars }

