// Ported from Sera UI (MIT, (c) 2025 Sera UI) — https://github.com/seraui/seraui/blob/main/src/app/docs/verify-badge/verify-badge.tsx

import { useId, useRef } from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

type VerifyTier = "basic" | "gold" | "premium"

export interface VerifyBadgeProps {
  type?: VerifyTier
  showLabel?: boolean
  label?: string
  className?: string
}

const labels: Record<VerifyTier, string> = {
  basic: "Verified",
  gold: "Gold verified",
  premium: "Premium verified",
}

function cssName(id: string) {
  return id.replace(/[^a-zA-Z0-9_-]/g, "")
}

export function VerifyBadge({ type = "basic", showLabel = true, label, className }: VerifyBadgeProps) {
  const rootRef = useRef<HTMLSpanElement>(null)
  const live = useAnimationActive(rootRef)
  const reduced = usePrefersReducedMotion()
  const id = cssName(useId())
  const text = label ?? labels[type]
  const spin = type === "premium" && live && !reduced
  const tone =
    type === "gold"
      ? "border-amber-500/40 bg-amber-500/10 text-amber-700 dark:text-amber-200"
      : type === "premium"
        ? "border-primary/40 bg-primary/10 text-primary"
        : "border-sky-500/40 bg-sky-500/10 text-sky-700 dark:text-sky-200"

  return (
    <span
      ref={rootRef}
      className={cn(
        "inline-flex items-center gap-2 rounded-full border px-3 py-1.5 text-sm font-medium shadow-sm outline-none focus-visible:ring-2 focus-visible:ring-ring",
        tone,
        className,
      )}
      tabIndex={0}
    >
      {type === "basic" ? <BasicMark /> : null}
      {type === "gold" ? <GoldMark id={id} /> : null}
      {type === "premium" ? <PremiumMark id={id} spin={spin} /> : null}
      {showLabel ? <span>{text}</span> : <span className="sr-only">{text}</span>}
    </span>
  )
}

function BasicMark() {
  return (
    <svg viewBox="0 0 24 24" className="size-5" aria-hidden="true">
      <path d="M12 2 4 6v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V6l-8-4z" fill="currentColor" fillOpacity="0.12" stroke="currentColor" strokeWidth="1.5" />
      <path d="m9 12 2 2 4-4" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

function GoldMark({ id }: { id: string }) {
  const gradient = `gold-${id}`
  return (
    <svg viewBox="0 0 24 24" className="size-5" aria-hidden="true">
      <circle cx="12" cy="12" r="10" fill={`url(#${gradient})`} fillOpacity="0.25" stroke={`url(#${gradient})`} strokeWidth="1.5" />
      <path d="m9.2 12.2 1.8 1.8 3.8-3.8" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
      <defs>
        <linearGradient id={gradient} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="var(--foreground)" />
          <stop offset="100%" stopColor="var(--primary)" />
        </linearGradient>
      </defs>
    </svg>
  )
}

function PremiumMark({ id, spin }: { id: string; spin: boolean }) {
  const animation = `spin-${id}`
  return (
    <svg viewBox="0 0 24 24" className="size-5" aria-hidden="true">
      <style>{`@keyframes ${animation} { to { transform: rotate(360deg); } }`}</style>
      <circle
        cx="12"
        cy="12"
        r="10"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeDasharray="3 3"
        className="origin-center motion-reduce:[animation:none]"
        style={{
          transformOrigin: "12px 12px",
          animationName: spin ? animation : "none",
          animationDuration: "8s",
          animationTimingFunction: "linear",
          animationIterationCount: "infinite",
          animationPlayState: spin ? "running" : "paused",
        }}
      />
      <path d="m10.4 12.1 1.2 1.2 2.4-2.4" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
    </svg>
  )
}

"use client"

// Ported from Fancy Components (MIT, (c) 2024 Daniel Petho) — https://github.com/danielpetho/fancy/blob/main/src/fancy/components/text/vertical-cut-reveal.tsx

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/utils"

import { motion, type AnimationOptions } from "motion/react"
import { forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useState } from "react"

export interface VerticalCutRevealProps {
  children: React.ReactNode
  reverse?: boolean
  transition?: AnimationOptions
  splitBy?: "words" | "characters" | "lines" | string
  staggerDuration?: number
  staggerFrom?: "first" | "last" | "center" | "random" | number
  containerClassName?: string
  wordLevelClassName?: string
  elementLevelClassName?: string
  onClick?: () => void
  onStart?: () => void
  onComplete?: () => void
  autoStart?: boolean
}

export interface VerticalCutRevealRef {
  startAnimation: () => void
  reset: () => void
}

interface Segment {
  characters: string[]
  needsSpace: boolean
}

const spring: AnimationOptions = { type: "spring", stiffness: 190, damping: 22 }

function splitIntoCharacters(text: string): string[] {
  if (typeof Intl !== "undefined" && "Segmenter" in Intl) {
    const segmenter = new Intl.Segmenter("en", { granularity: "grapheme" })
    return Array.from(segmenter.segment(text), ({ segment }) => segment)
  }
  return Array.from(text)
}

function toSegments(text: string, splitBy: string): Segment[] {
  const words = text.split(" ")
  if (splitBy === "characters") {
    return words.map((word, index) => ({
      characters: splitIntoCharacters(word),
      needsSpace: index !== words.length - 1,
    }))
  }
  const parts = splitBy === "words" ? words : splitBy === "lines" ? text.split("\n") : text.split(splitBy)
  return parts.map((part, index) => ({
    characters: [part],
    needsSpace: index !== parts.length - 1,
  }))
}

function transitionDelay(transition: AnimationOptions): number {
  if ("delay" in transition && typeof transition.delay === "number") return transition.delay
  return 0
}

export const VerticalCutReveal = forwardRef<VerticalCutRevealRef, VerticalCutRevealProps>(function VerticalCutReveal(
  {
    children,
    reverse = false,
    transition = spring,
    splitBy = "words",
    staggerDuration = 0.2,
    staggerFrom = "first",
    containerClassName,
    wordLevelClassName,
    elementLevelClassName,
    onClick,
    onStart,
    onComplete,
    autoStart = true,
  },
  ref,
) {
  const text = typeof children === "string" ? children : children == null ? "" : String(children)
  const [isAnimating, setIsAnimating] = useState(false)
  const prefersReducedMotion = usePrefersReducedMotion()
  const elements = useMemo(() => toSegments(text, splitBy), [splitBy, text])

  const getStaggerDelay = useCallback(
    (index: number) => {
      const total =
        splitBy === "characters"
          ? elements.reduce((acc, word) => acc + word.characters.length + (word.needsSpace ? 1 : 0), 0)
          : elements.length
      if (staggerFrom === "first") return index * staggerDuration
      if (staggerFrom === "last") return (total - 1 - index) * staggerDuration
      if (staggerFrom === "center") return Math.abs(Math.floor(total / 2) - index) * staggerDuration
      if (staggerFrom === "random") {
        const randomIndex = Math.floor(Math.random() * total)
        return Math.abs(randomIndex - index) * staggerDuration
      }
      return Math.abs(staggerFrom - index) * staggerDuration
    },
    [elements, splitBy, staggerDuration, staggerFrom],
  )

  const startAnimation = useCallback(() => {
    setIsAnimating(true)
    onStart?.()
  }, [onStart])

  useImperativeHandle(ref, () => ({
    startAnimation,
    reset: () => setIsAnimating(false),
  }))

  useEffect(() => {
    if (!autoStart || prefersReducedMotion) return
    queueMicrotask(() => startAnimation())
  }, [autoStart, prefersReducedMotion, startAnimation])

  const variants = {
    hidden: { y: prefersReducedMotion ? 0 : reverse ? "-100%" : "100%" },
    visible: (index: number) => ({
      y: 0,
      transition: prefersReducedMotion
        ? { duration: 0 }
        : { ...transition, delay: transitionDelay(transition) + getStaggerDelay(index) },
    }),
  }

  const revealed = prefersReducedMotion || isAnimating

  return (
    <span
      className={cn("flex flex-wrap whitespace-pre-wrap", splitBy === "lines" && "flex-col", containerClassName)}
      data-reduced={prefersReducedMotion ? "true" : "false"}
      data-slot="vertical-cut-reveal"
      onClick={onClick}
    >
      <span className="sr-only">{text}</span>
      {elements.map((wordObj, wordIndex, array) => {
        const previousCharsCount = array.slice(0, wordIndex).reduce((sum, word) => sum + word.characters.length, 0)
        const lastWord = wordIndex === array.length - 1
        return (
          <span aria-hidden="true" className={cn("inline-flex overflow-hidden", wordLevelClassName)} key={wordIndex}>
            {wordObj.characters.map((char, charIndex) => (
              <span className={cn("relative whitespace-pre-wrap", elementLevelClassName)} key={charIndex}>
                <motion.span
                  animate={revealed ? "visible" : "hidden"}
                  className="inline-block"
                  custom={previousCharsCount + charIndex}
                  initial={prefersReducedMotion ? "visible" : "hidden"}
                  onAnimationComplete={lastWord && charIndex === wordObj.characters.length - 1 ? onComplete : undefined}
                  variants={variants}
                >
                  {char}
                </motion.span>
              </span>
            ))}
            {wordObj.needsSpace ? <span> </span> : null}
          </span>
        )
      })}
    </span>
  )
})

"use client"

import * as React from "react"

import { useAnimationActive } from "@/hooks/use-animation-active"
import { textStyle } from "@/lib/text-style"
import { cn } from "@/lib/utils"

export type VfxKind = "glitch" | "glow" | "crt" | "rgb-shift" | "pixelate"

export interface VfxElementProps {
  effects?: VfxKind[]
  className?: string
  children?: React.ReactNode
  /** 特效强度。不传则按开关原样叠加。 */
  intensity?: number
  fontSize?: number
  fontWeight?: number
  letterSpacing?: number
  align?: "left" | "center" | "right"
}

const COMBINED = `
precision highp float;
uniform vec2 resolution;
uniform vec2 offset;
uniform float time;
uniform bool autoCrop;
uniform sampler2D src;
uniform float uGlitch;
uniform float uGlow;
uniform float uCrt;
uniform float uRgb;
uniform float uPixel;
out vec4 outColor;

vec4 readTex(sampler2D tex, vec2 uv) {
  if (autoCrop && (uv.x < 0. || uv.x > 1. || uv.y < 0. || uv.y > 1.)) return vec4(0);
  return texture(tex, uv);
}

void main() {
  vec2 uv = (gl_FragCoord.xy - offset) / resolution;
  float cell = mix(1.0, 18.0, uPixel);
  vec2 puv = floor(uv * resolution / cell) * cell / resolution;
  puv = mix(uv, puv, uPixel);

  float g = step(0.92, fract(sin(floor(time * 12.0) * 78.2) * 43758.5));
  puv.x += (g * 0.03 - 0.015) * uGlitch;
  puv.y += sin(puv.x * 40.0 + time * 8.0) * 0.006 * uGlitch;

  vec4 base = readTex(src, puv);
  vec4 r = readTex(src, puv + vec2(0.008 * uRgb, 0.0));
  vec4 b = readTex(src, puv - vec2(0.008 * uRgb, 0.0));
  vec4 color = vec4(r.r, base.g, b.b, max(base.a, max(r.a, b.a)));

  float scan = sin((uv.y + time * 0.04) * resolution.y * 1.15) * 0.12 * uCrt;
  color.rgb *= 1.0 - scan;
  color.rgb *= mix(1.0, 0.78 + 0.22 * sin(uv.y * 220.0), uCrt);

  vec3 glow = color.rgb * (0.35 + 0.65 * color.rgb);
  color.rgb = mix(color.rgb, color.rgb + glow * 0.55, uGlow);
  outColor = color;
}
`

function flag(effects: VfxKind[], name: VfxKind) {
  return effects.includes(name) ? 1 : 0
}

function fallbackClass(effects: VfxKind[]) {
  return cn(
    effects.includes("glitch") && "animate-pulse",
    effects.includes("glow") && "shadow-[0_0_28px_color-mix(in_oklab,var(--primary)_55%,transparent)]",
    effects.includes("crt") && "[background-image:repeating-linear-gradient(to_bottom,transparent,transparent_2px,rgb(0_0_0/18%)_3px)]",
    effects.includes("rgb-shift") && "[text-shadow:2px_0_#f43f5e,-2px_0_#22d3ee]",
    effects.includes("pixelate") && "[image-rendering:pixelated]",
  )
}

function useReducedMotion() {
  return React.useSyncExternalStore(
    (onChange) => {
      const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
      mq.addEventListener("change", onChange)
      return () => mq.removeEventListener("change", onChange)
    },
    () => window.matchMedia("(prefers-reduced-motion: reduce)").matches,
    () => false,
  )
}

function VfxElement({
  effects = ["glitch"],
  className,
  children,
  intensity,
  fontSize,
  fontWeight,
  letterSpacing,
  align,
}: VfxElementProps) {
  const hostRef = React.useRef<HTMLDivElement>(null)
  const targetRef = React.useRef<HTMLDivElement>(null)
  const reduced = useReducedMotion()
  const active = useAnimationActive(hostRef)
  const [fallback, setFallback] = React.useState(false)
  const key = effects.join(",")
  const gain = intensity === undefined ? 1 : intensity

  React.useEffect(() => {
    const host = hostRef.current
    const target = targetRef.current
    if (!host || !target || reduced || !active) return

    let disposed = false
    let instance: { destroy: () => void } | null = null

    const selected = key.split(",") as VfxKind[]
    void import("@vfx-js/core").then(({ VFX }) => {
      if (disposed) return
      const vfx = VFX.init({
        wrapper: host,
        zIndex: 2,
        pixelRatio: Math.min(window.devicePixelRatio || 1, 1.5),
        scrollPadding: false,
      })
      if (!vfx) {
        queueMicrotask(() => setFallback(true))
        return
      }
      instance = vfx
      void vfx.add(target, {
        shader: COMBINED,
        overflow: 28,
        uniforms: {
          uGlitch: flag(selected, "glitch") * gain,
          uGlow: flag(selected, "glow") * gain,
          uCrt: flag(selected, "crt") * gain,
          uRgb: flag(selected, "rgb-shift") * gain,
          uPixel: flag(selected, "pixelate") * gain,
        },
      })
    })

    return () => {
      disposed = true
      instance?.destroy()
    }
  }, [active, gain, key, reduced])

  return (
    <div ref={hostRef} className={cn("relative overflow-hidden rounded-xl", className)}>
      <div
        ref={targetRef}
        className={cn("grid min-h-40 place-items-center bg-zinc-950 px-6 py-8 text-center text-white", (fallback || reduced) && fallbackClass(effects))}
        style={textStyle(undefined, fontSize, fontWeight, letterSpacing, align)}
      >
        {children ?? <p className="font-display text-3xl">VFX</p>}
      </div>
    </div>
  )
}

export { VfxElement }

