    const id = window.setTimeout(() => setCount((current) => current + 1), 520)
    return () => window.clearTimeout(id)
  }, [count])

  return (
    <TextGenerate
      className="w-full"
      text={STREAM.slice(0, count).join(" ")}
      duration={duration}
      delay={delay}
      fontSize={fontSize}
      fontWeight={fontWeight}
