  ])
  return (
    <ReactionBar
      items={items}
      duration={duration}
      scale={scale}
      gap={gap}
      color={color}
      onToggle={(emoji) =>
        setItems((current) =>
          current.map((item) =>
            item.emoji === emoji ? { ...item, active: !item.active, count: item.count + (item.active ? -1 : 1) } : item,
          ),
        )
      }
    />
  )
}

